// NOTE: Once a backend exists, this client-side URL encoding approach should be replaced with a database-backed share link (e.g. /trips/:id/share/:token) to avoid long URLs for complex itineraries -- this client-only version is a reasonable interim approach given no backend yet.

import React, { useState } from "react";
import { X, Copy, Check, Share2, Link, Sparkles } from "lucide-react";
import { ItineraryConfig } from "./ItineraryView";
import { getShareableUrl } from "../utils/shareUrl";

interface ShareItineraryModalProps {
  config: ItineraryConfig;
  cityName: string;
  isOpen: boolean;
  onClose: () => void;
}

export const ShareItineraryModal: React.FC<ShareItineraryModalProps> = ({
  config,
  cityName,
  isOpen,
  onClose,
}) => {
  const [copied, setCopied] = useState<boolean>(false);

  // Keyboard Escape listener
  React.useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const shareUrl = getShareableUrl(config);
  const canNativeShare = typeof navigator !== "undefined" && !!navigator.share;

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    } catch (err) {
      console.error("Failed to copy link:", err);
    }
  };

  const handleNativeShare = async () => {
    if (!navigator.share) return;
    try {
      await navigator.share({
        title: `Shared Itinerary for ${cityName}`,
        text: `Check out this circular ${config.tripDays || 2}-day heritage itinerary for ${cityName}!`,
        url: shareUrl,
      });
    } catch (err: any) {
      if (err?.name !== "AbortError") {
        console.warn("Native share could not be completed:", err);
      }
    }
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="share-itinerary-title"
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-ink/70 backdrop-blur-xs animate-fadeIn"
      onClick={onClose}
    >
      <div
        className="bg-salt border-2 border-gold max-w-lg w-full p-6 shadow-2xl relative font-sans rounded-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-stone hover:text-charcoal p-1 transition-colors cursor-pointer rounded-lg"
          aria-label="Close Share Modal"
        >
          <X className="w-5 h-5" />
        </button>

        {/* Modal Header */}
        <div className="flex items-center gap-3 border-b border-stone/30 pb-4 mb-4">
          <div className="p-2.5 bg-gold/20 border border-gold text-ink rounded-xl">
            <Share2 className="w-5 h-5 text-gold" />
          </div>
          <div>
            <h3 className="font-display font-bold text-lg text-ink">
              Share Itinerary
            </h3>
            <p className="text-xs text-stone font-mono">
              {cityName} � {config.tripDays || 2}-Day Circular Route
            </p>
          </div>
        </div>

        {/* Info Banner */}
        <p className="text-xs text-charcoal bg-white border border-stone/30 p-3 mb-4 font-mono leading-relaxed rounded-xl">
          Generates a read-only shareable link containing the complete itinerary
          routing, timed stops, and daily breakdown.
        </p>

        {/* Link Input + Copy Button */}
        <div className="space-y-3 mb-6">
          <label className="block text-xs font-mono font-bold text-stone uppercase tracking-wider">
            Shareable Link
          </label>

          <div className="flex items-center gap-2">
            <div className="relative flex-1">
              <input
                type="text"
                readOnly
                value={shareUrl}
                className="w-full bg-white border border-stone/40 px-3 py-2 text-xs font-mono text-charcoal select-all focus:outline-none focus:border-gold rounded-lg"
              />
              <Link className="w-3.5 h-3.5 text-stone absolute right-3 top-2.5 pointer-events-none" />
            </div>

            <button
              onClick={handleCopy}
              className={`inline-flex items-center gap-1.5 px-4 py-2 text-xs font-mono font-bold border transition-colors cursor-pointer shrink-0 rounded-lg ${
                copied
                  ? "bg-emerald-800 text-white border-emerald-900 shadow-xs"
                  : "bg-gold hover:bg-gold/90 text-ink border-ink shadow-xs"
              }`}
            >
              {copied ? (
                <>
                  <Check className="w-3.5 h-3.5 text-white" />
                  <span>Copied!</span>
                </>
              ) : (
                <>
                  <Copy className="w-3.5 h-3.5 text-ink" />
                  <span>Copy link</span>
                </>
              )}
            </button>
          </div>
        </div>

        {/* Action Buttons: Native Share Sheet (if supported on mobile) */}
        {canNativeShare && (
          <div className="mb-4">
            <button
              onClick={handleNativeShare}
              className="w-full bg-ink hover:bg-ink/90 text-salt border border-gold px-4 py-2.5 text-xs font-mono font-bold flex items-center justify-center gap-2 transition-colors cursor-pointer shadow-xs rounded-lg"
            >
              <Share2 className="w-4 h-4 text-gold" />
              <span>Open Native Share Sheet</span>
            </button>
          </div>
        )}

        {/* Footer Note */}
        <div className="pt-3 border-t border-stone/20 flex items-center justify-between text-[11px] font-mono text-stone">
          <span>Read-only preview</span>
          <button
            onClick={onClose}
            className="text-stone hover:text-charcoal underline cursor-pointer"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

frontend/src/App.tsx:
import React, { useState, useEffect, useCallback, useRef } from "react";
import { LanguageProvider } from "./context/LanguageContext";
import { ThemeProvider } from "./context/ThemeContext";
import { Navbar } from "./components/Navbar";
import { Hero } from "./components/Hero";
import { ValueProps } from "./components/ValueProps";
import { ExploreView } from "./components/ExploreView";
import { DestinationDetailView } from "./components/DestinationDetailView";
import { ItineraryView, ItineraryConfig } from "./components/ItineraryView";
import { BudgetPlannerView } from "./components/BudgetPlannerView";
import { HotelsView } from "./components/HotelsView";
import { ProfileDashboardView } from "./components/ProfileDashboardView";
import { AdminDashboardView } from "./components/AdminDashboardView";
import { Footer } from "./components/Footer";
import { PlannerModal } from "./components/PlannerModal";
import { AuthView } from "./components/AuthView";
import { HomeTransitionOverlay } from "./components/HomeTransitionOverlay";
import { OfflineBanner } from "./components/OfflineBanner";
import { PwaInstallPrompt } from "./components/PwaInstallPrompt";
import { getLatestOfflineTrip } from "./utils/offlineStorage";
import {
  navigate,
  getCurrentRoute,
  subscribeToRoute,
  RouteState,
} from "./utils/router";

const LazyResearchView = React.lazy(() =>
  import.meta.env.DEV
    ? import("./components/ResearchView").then((m) => ({ default: m.ResearchView }))
    : Promise.resolve({ default: () => null as any })
);
import { getSharedFromUrl, clearSharedUrl } from "./utils/shareUrl";
import { InvalidSharedLinkView } from "./components/InvalidSharedLinkView";
import { NotFoundView } from "./components/NotFoundView";
import { ImageWithFallback } from "./components/ImageWithFallback";
import type { Destination } from "./api/types";
import { api, useApi, useCatalog, session, EMPTY_DESTINATION } from "./api";
import { MapPin } from "lucide-react";
import { motion, AnimatePresence } from "motion/react";

// --- Session-storage helpers for itinerary persistence across refresh -------
const ITINERARY_SESSION_KEY = "heritage_active_itinerary_v1";

function saveItineraryToSession(cfg: ItineraryConfig | null) {
  if (cfg) {
    sessionStorage.setItem(ITINERARY_SESSION_KEY, JSON.stringify(cfg));
  } else {
    sessionStorage.removeItem(ITINERARY_SESSION_KEY);
  }
}

function restoreItineraryFromSession(): ItineraryConfig | null {
  try {
    const raw = sessionStorage.getItem(ITINERARY_SESSION_KEY);
    return raw ? (JSON.parse(raw) as ItineraryConfig) : null;
  } catch {
    return null;
  }
}

export default function App() {
  const catalog = useCatalog();
  const destinations = catalog.data ?? [];
  const getCityById = (id: string) => destinations.find(d => d.id === id);
  const [authRevision, setAuthRevision] = useState(0);
  const authRequest = useApi(signal => api.me(signal), [authRevision]);
  useEffect(() => {
    const changed = () => { setCurrentUser(null); setAuthRevision(n => n + 1); };
    window.addEventListener("heritage-auth-change", changed);
    return () => window.removeEventListener("heritage-auth-change", changed);
  }, []);
  useEffect(() => { setCurrentUser(authRequest.data ?? null); }, [authRequest.data]);
  const [selectedDestination, setSelectedDestination] =
    useState<Destination | null>(null);
  const [plannerOpen, setPlannerOpen] = useState<boolean>(false);
  const [preselectedForPlanner, setPreselectedForPlanner] =
    useState<Destination | null>(null);

  // Active Generated Itinerary Config & View Mode
  const [activeItinerary, setActiveItinerary] =
    useState<ItineraryConfig | null>(null);
  const [isReadOnlyItinerary, setIsReadOnlyItinerary] =
    useState<boolean>(false);
  const [showBudgetPlanner, setShowBudgetPlanner] = useState<boolean>(false);
  const [showHotels, setShowHotels] = useState<boolean>(false);
  const [showProfile, setShowProfile] = useState<boolean>(false);
  const [showAdminDashboard, setShowAdminDashboard] = useState<boolean>(false);

  // Dev-only Research Simulation Mode
  const [showResearchMode, setShowResearchMode] = useState<boolean>(false);
  const [showNotFound, setShowNotFound] = useState<string | null>(null);

  // Shared Link Error State
  const [sharedLinkError, setSharedLinkError] = useState<{
    error: string;
    rawPayload: string;
  } | null>(null);

  // --- Auth State (restored from localStorage) -------------------------------
  const [currentUser, setCurrentUser] = useState<{
    name: string;
    email: string;
    role: "tourist" | "operator";
  } | null>(null);
  const currentUserRef = useRef(currentUser);
  currentUserRef.current = currentUser;

  // --- Sync state from a parsed route -----------------------------------------
  const syncStateFromRoute = useCallback(
    (route: RouteState) => {
      // Helper: reset all overlay views
      const clearOverlays = () => {
        setShowHotels(false);
        setShowBudgetPlanner(false);
        setShowProfile(false);
        setShowAdminDashboard(false);
        setShowResearchMode(false);
        setSharedLinkError(null);
        setShowNotFound(null);
        setAuthMode(null);
      };

      switch (route.type) {
        case "home":
        case "explore":
          clearOverlays();
          setSelectedDestination(null);
          setActiveItinerary(null);
          break;

        case "destination": {
          clearOverlays();
          setSelectedDestination({...EMPTY_DESTINATION, id: route.destinationId ?? ""});
          setActiveItinerary(null);

          break;
        }

        case "hotels":
          clearOverlays();
          setSelectedDestination(null);
          setShowHotels(true);
          break;

        case "budget":
          clearOverlays();
          setSelectedDestination(null);
          setShowBudgetPlanner(true);
          setActiveItinerary(restoreItineraryFromSession());
          break;

        case "itinerary": {
          // Restore from sessionStorage if no in-memory itinerary yet
          const stored = restoreItineraryFromSession();
          if (stored) {
            clearOverlays();
            setSelectedDestination(null);
            setActiveItinerary(stored);
          } else {
            // No itinerary to show ? redirect home
            navigate("/", { replace: true });
          }
          break;
        }

        case "profile": {
          const user = currentUserRef.current || session.token();
          if (!user) {
            navigate("/login", { replace: true });
            break;
          }
          clearOverlays();
          setSelectedDestination(null);
          setShowProfile(true);
          break;
        }

        case "admin": {
          const user = currentUserRef.current || session.token();
          if (!user) {
            navigate("/login", { replace: true });
            break;
          }
          clearOverlays();
          setSelectedDestination(null);
          setShowAdminDashboard(true);
          break;
        }

        case "auth":
          clearOverlays();
          setSelectedDestination(null);
          setActiveItinerary(null);
          setAuthMode(route.authMode ?? "login");
          break;

        case "research":
          if (import.meta.env.DEV) {
            clearOverlays();
            setSelectedDestination(null);
            setShowResearchMode(true);
          } else {
            navigate("/", { replace: true });
          }
          break;

        case "not-found":
          clearOverlays();
          setSelectedDestination(null);
          setActiveItinerary(null);
          setShowNotFound(route.path);
          break;

        default:
          // Soft-redirect home; no 404 page needed for this SPA
          navigate("/", { replace: true });
          break;
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  // --- Mount: parse URL + subscribe to future route changes (popstate) ---------
  useEffect(() => {
    // 1. Check for a shared-link itinerary first (takes precedence)
    const sharedData = getSharedFromUrl();
    if (sharedData && sharedData.success === true) {
      setActiveItinerary(sharedData.config);
      saveItineraryToSession(sharedData.config);
      setIsReadOnlyItinerary(true);
      navigate("/itinerary", { replace: true });
      return;
    } else if (sharedData && sharedData.success === false) {
      setSharedLinkError({
        error: sharedData.error,
        rawPayload: sharedData.rawPayload,
      });
      return;
    }

    // 2. Sync state from current URL
    syncStateFromRoute(getCurrentRoute());

    // 3. Subscribe so browser Back/Forward updates state
    const unsubscribe = subscribeToRoute(syncStateFromRoute);
    return unsubscribe;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Offline & PWA Install State
  const [isOffline, setIsOffline] = useState<boolean>(
    typeof navigator !== "undefined" ? !navigator.onLine : false,
  );
  const [offlineCityName, setOfflineCityName] = useState<string>("");
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showPwaPrompt, setShowPwaPrompt] = useState<boolean>(false);

  // 1. Offline detection and auto-routing to cached itinerary
  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => {
      setIsOffline(true);
      const cached = getLatestOfflineTrip();
      if (cached) {
        setOfflineCityName(cached.cityName);
        setActiveItinerary(cached.config);
        setSelectedDestination(null);
        setShowHotels(false);
        setShowProfile(false);
        setShowAdminDashboard(false);
        setAuthMode(null);
      }
    };

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    if (typeof navigator !== "undefined" && !navigator.onLine) {
      handleOffline();
    }

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  // 2. Capture native beforeinstallprompt PWA event
  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };

    window.addEventListener("beforeinstallprompt", handleBeforeInstallPrompt);
    return () => {
      window.removeEventListener(
        "beforeinstallprompt",
        handleBeforeInstallPrompt,
      );
    };
  }, []);

  // 3. Surface PWA prompt ONCE non-intrusively AFTER user views a generated itinerary
  useEffect(() => {
    if (activeItinerary) {
      const isDismissed = localStorage.getItem(
        "heritage_pwa_prompt_dismissed_v1",
      );
      if (!isDismissed) {
        const timer = setTimeout(() => {
          setShowPwaPrompt(true);
        }, 1200);
        return () => clearTimeout(timer);
      }
    }
  }, [activeItinerary]);

  // In-memory Trip Builder list state
  const [tripList, setTripList] = useState<Destination[]>([]);

  // Preferred stay selection mapping: cityId -> hotelId
  const [preferredHotels, setPreferredHotels] = useState<
    Record<string, string>
  >({});

  const handleSetPreferredHotel = (cityId: string, hotelId: string) => {
    setPreferredHotels((prev) => ({
      ...prev,
      [cityId]: hotelId,
    }));
  };

  // Auth State
  const [authMode, setAuthMode] = useState<"login" | "register" | null>(null);

  const handleToggleTripItem = (dest: Destination) => {
    setTripList((prev) => {
      const exists = prev.some((item) => item.id === dest.id);
      if (exists) {
        return prev.filter((item) => item.id !== dest.id);
      } else {
        return [...prev, dest];
      }
    });
  };

  const handleOpenPlannerWithSite = (dest: Destination) => {
    setPreselectedForPlanner(dest);
    setPlannerOpen(true);
  };

  // --- Persist activeItinerary to sessionStorage on every change ---------------
  useEffect(() => {
    if(activeItinerary?.tripId) saveItineraryToSession(activeItinerary);
  }, [activeItinerary]);

  // --- Persist currentUser to localStorage on every change ---------------------
  const handleLogout = useCallback(() => {
    // Clear persisted user
    session.clear();
    setActiveItinerary(null);
    saveItineraryToSession(null);
    setCurrentUser(null);
    // Reset all overlay/view states
    setShowAdminDashboard(false);
    setShowProfile(false);
    setShowResearchMode(false);
    setShowBudgetPlanner(false);
    setShowHotels(false);
    setAuthMode(null);
    // Navigate to home page
    navigate("/");
  }, []);

  const handleNavigateSection = (sectionId: string) => {
    switch (sectionId) {
      case "admin":
        if (currentUserRef.current || session.token()) {
          navigate("/admin");
        } else {
          navigate("/login");
        }
        return;

      case "profile":
      case "dashboard":
        if (currentUserRef.current || session.token()) {
          navigate("/profile");
        } else {
          navigate("/login");
        }
        return;

      case "budget":
        navigate("/budget");
        return;

      case "hotels":
        navigate("/hotels");
        return;

      case "account":
        if (currentUserRef.current || session.token()) {
          navigate("/profile");
        } else {
          navigate("/login");
        }
        return;

      case "home":
        navigate("/");
        return;

      default:
        // For hash-scroll targets (explore, about, etc.) go home first then scroll
        navigate("/", { preserveScroll: true });
        setTimeout(() => {
          const el = document.getElementById(sectionId);
          if (el) {
            el.scrollIntoView({ behavior: "smooth" });
          } else {
            window.scrollTo({ top: 0, behavior: "smooth" });
          }
        }, 80);
    }
  };

  const handleSelectNearby = (destId: string) => {
    const found = destinations.find((d) => d.id === destId);
    if (found) {
      navigate(`/destination/${found.id}`);
    }
  };

  return (
    <ThemeProvider>
      <LanguageProvider>
        <div className="min-h-screen bg-salt text-charcoal font-body flex flex-col selection:bg-gold selection:text-ink">
          {/* Persistent Offline Banner */}
          {isOffline && (
            <OfflineBanner
              cityName={offlineCityName || activeItinerary?.cityId}
              hasCachedItinerary={!!getLatestOfflineTrip()}
            />
          )}

          {/* 1. Nav bar */}
          <Navbar
            onOpenPlanner={() => {
              setPreselectedForPlanner(null);
              setPlannerOpen(true);
            }}
            onNavigateSection={handleNavigateSection}
            onOpenAuth={(mode) => {
              navigate(mode === "register" ? "/register" : "/login");
            }}
            user={currentUser}
            onLogout={handleLogout}
            tripCount={tripList.length}
          />

          {/* Main Content Area */}
          <main className="flex-grow">
            <AnimatePresence mode="wait">
              {((showProfile || showAdminDashboard) && authRequest.loading) ? <p role="status">Checking your session...</p>
                : ((showProfile || showAdminDashboard) && authRequest.error) ? <p role="alert">{authRequest.error} <button onClick={authRequest.reload}>Retry</button></p>
                : sharedLinkError ? (
                <motion.div
                  key="invalid-shared-link"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <InvalidSharedLinkView
                    errorMessage={sharedLinkError.error}
                    rawPayload={sharedLinkError.rawPayload}
                    onExplore={() => {
                      setSharedLinkError(null);
                      navigate("/", { preserveScroll: true });
                      setTimeout(() => {
                        document
                          .getElementById("explore")
                          ?.scrollIntoView({ behavior: "smooth" });
                      }, 80);
                    }}
                    onPlanTrip={() => {
                      setSharedLinkError(null);
                      navigate("/");
                      setPlannerOpen(true);
                    }}
                    onGoHome={() => {
                      setSharedLinkError(null);
                      navigate("/");
                    }}
                  />
                </motion.div>
              ) : showNotFound ? (
                /* Display 404 Route Not Found View */
                <motion.div
                  key="not-found-view"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <NotFoundView invalidPath={showNotFound} />
                </motion.div>
              ) : showResearchMode && import.meta.env.DEV ? (
                <motion.div
                  key="research-view"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <React.Suspense fallback={<div className="font-mono text-center p-8">Loading Research Matrix...</div>}>
                    <LazyResearchView
                      onBack={() => navigate("/")}
                    />
                  </React.Suspense>
                </motion.div>
              ) : selectedDestination ? (
                <motion.div
                  key="destination-detail"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35, ease: [0.16, 1, 0.3, 1] }}
                >
                  <DestinationDetailView
                    destination={selectedDestination}
                    preferredHotels={preferredHotels}
                    onSelectPreferredHotel={handleSetPreferredHotel}
                    onBack={() => navigate("/")}
                    onAddToTrip={handleToggleTripItem}
                    isAddedToTrip={tripList.some(
                      (d) => d.id === selectedDestination.id,
                    )}
                    onSelectNearbyDestination={handleSelectNearby}
                    onOpenPlannerWithSite={handleOpenPlannerWithSite}
                  />
                </motion.div>
              ) : authMode ? (
                /* If Auth Mode active, display full Auth View */
                <motion.div
                  key="auth-view"
                  initial={{ opacity: 0, scale: 0.98 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.98 }}
                  transition={{ duration: 0.3 }}
                >
                  <AuthView
                    initialMode={authMode}
                    onCloseOrGuest={() => navigate("/")}
                    onAuthSuccess={(user) => {
                      setCurrentUser(user);
                      navigate("/profile");
                    }}
                  />
                </motion.div>
              ) : (showAdminDashboard && Boolean(currentUser)) ? (
                /* Display Admin Dashboard View */
                <motion.div
                  key="admin-dashboard"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <AdminDashboardView
                    onBackToProfile={() => navigate("/profile")}
                  />
                </motion.div>
              ) : (showProfile && Boolean(currentUser)) ? (
                /* Display Profile & Dashboard View */
                <motion.div
                  key="profile-view"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <ProfileDashboardView
                    currentUser={currentUser}
                    onOpenItinerary={(config) => {
                      saveItineraryToSession(config);
                      setActiveItinerary(config);
                      navigate("/itinerary");
                    }}
                    onOpenExplore={() => {
                      navigate("/", { preserveScroll: true });
                      setTimeout(() => {
                        document.getElementById("explore")?.scrollIntoView({ behavior: "smooth" });
                      }, 80);
                    }}
                    onOpenPlanner={() => {
                      setShowProfile(false);
                      setPlannerOpen(true);
                    }}
                    onOpenAdminDashboard={currentUser ? () => navigate("/admin") : undefined}
                    onLogout={handleLogout}
                  />
                </motion.div>
              ) : showHotels ? (
                /* Display Ranked Hotels Page */
                <motion.div
                  key="hotels-view"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <HotelsView
                    selectedCityId={activeItinerary?.cityId}
                    preferredHotels={preferredHotels}
                    onSelectPreferredHotel={handleSetPreferredHotel}
                    onSelectDestination={(dest) => {
                      navigate(`/destination/${dest.id}`);
                    }}
                    onOpenPlanner={() => {
                      setShowHotels(false);
                      setPlannerOpen(true);
                    }}
                  />
                </motion.div>
              ) : showBudgetPlanner ? (
                /* Display Budget Planner Page */
                <motion.div
                  key="budget-view"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <BudgetPlannerView
                    config={activeItinerary}
                    onBackToItinerary={() => {
                      if (!activeItinerary?.tripId) { setPlannerOpen(true); return; }
                      navigate("/itinerary");
                    }}
                    onBackToPlanner={() => {
                      setShowBudgetPlanner(false);
                      setPlannerOpen(true);
                    }}
                    onSelectDestination={(dest) => {
                      navigate(`/destination/${dest.id}`);
                    }}
                  />
                </motion.div>
              ) : activeItinerary ? (
                /* Display Generated Itinerary View */
                <motion.div
                  key="itinerary-view"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.35 }}
                >
                  <ItineraryView
                    config={activeItinerary}
                    onPersistedConfig={(config) => { setActiveItinerary(config); saveItineraryToSession(config); }}
                    preferredHotels={preferredHotels}
                    onSelectPreferredHotel={handleSetPreferredHotel}
                    onBackToPlanner={() => {
                      if (activeItinerary?.cityId) {
                        setPreselectedForPlanner(
                          getCityById(activeItinerary.cityId) || null,
                        );
                      }
                      setPlannerOpen(true);
                    }}
                    onSelectDestination={(dest) => {
                      navigate(`/destination/${dest.id}`);
                    }}
                    onOpenBudgetPlanner={() => navigate("/budget")}
                    isReadOnly={isReadOnlyItinerary}
                    onPlanOwnTrip={() => {
                      clearSharedUrl();
                      setIsReadOnlyItinerary(false);
                      setActiveItinerary(null);
                      navigate("/");
                      setTimeout(() => setPlannerOpen(true), 100);
                    }}
                  />
                </motion.div>
              ) : (
                /* Landing Page & Explore Views (Home Screen) */
                <motion.div
                  key="home-screen"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }}
                >
                  {/* Home Screen Entrance Transition Overlay & Gold Sweep */}
                  <HomeTransitionOverlay />

                  {/* 2. Hero Section */}
                  <Hero
                    onStartPlanning={() => {
                      setPreselectedForPlanner(null);
                      setPlannerOpen(true);
                    }}
                    onExploreClick={() => handleNavigateSection("explore")}
                  />

                  {/* 3. "Why this exists" Section */}
                  <ValueProps />

                  {/* 4. Full Explore & Search Page (Main Terrace Grid Search & Browse) */}
                  <ExploreView
                    onSelectDestination={(dest) => {
                      navigate(`/destination/${dest.id}`);
                    }}
                    onStartTripWithDestination={handleOpenPlannerWithSite}
                  />

                  {/* Heritage Haveli & Stays Section (For "Hotels" link) */}
                  <section
                    id="hotels"
                    className="bg-salt py-16 border-b border-stone/30"
                  >
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                      <div className="border-l-2 border-gold pl-4 mb-8">
                        <span className="font-mono text-xs text-gold uppercase tracking-widest block mb-1">
                          Preserved Heritage Accommodations
                        </span>
                        <h2 className="font-display text-2xl sm:text-3xl text-charcoal tracking-tight">
                          Heritage Havelis & Royal Palaces
                        </h2>
                        <p className="text-xs text-stone font-mono mt-1">
                          Authentic heritage homestays and restored royal guest
                          palaces near Gujarat�s monuments.
                        </p>
                      </div>

                      {catalog.loading && <p role="status">Loading stays...</p>}
                      {catalog.error && <p role="alert">{catalog.error} <button onClick={catalog.reload}>Retry</button></p>}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {destinations.flatMap(d => d.hotels).slice(0, 3).map(h => ({name:h.name,location:h.location,type:h.stayType,rate:h.pricePerNight,dist:h.description,img:h.imageUrl})).map((hotel, idx) => (
                          <div
                            key={idx}
                            className="bg-ink text-salt p-4 border border-stone/40 space-y-3"
                          >
                            <div className="relative h-44 overflow-hidden border border-stone/30">
                              <ImageWithFallback
                                src={hotel.img}
                                alt={hotel.name}
                                category="hotel"
                                className="w-full h-full object-cover hover:scale-105 transition-all duration-300"
                              />
                              <span className="absolute top-2 left-2 bg-salt text-ink font-mono text-[10px] px-2 py-0.5 uppercase">
                                {hotel.type}
                              </span>
                            </div>
                            <div>
                              <h3 className="font-display text-lg font-semibold text-salt">
                                {hotel.name}
                              </h3>
                              <span className="text-xs font-mono text-stone flex items-center gap-1">
                                <MapPin className="w-3 h-3 text-gold" />
                                {hotel.location}
                              </span>
                            </div>
                            <div className="flex items-center justify-between text-xs font-mono pt-2 border-t border-stone/30">
                              <span className="text-stone">{hotel.dist}</span>
                              <span className="text-gold font-semibold">
                                {hotel.rate}
                              </span>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </section>
                </motion.div>
              )}
            </AnimatePresence>
          </main>

          {/* 5. Footer */}
          <Footer
            onNavigateSection={handleNavigateSection}
            onOpenPlanner={() => {
              setPreselectedForPlanner(null);
              setPlannerOpen(true);
            }}
          />

          {/* Trip Planner Modal */}
          <PlannerModal
            isOpen={plannerOpen}
            onClose={() => setPlannerOpen(false)}
            preselectedDestination={preselectedForPlanner}
            initialConfig={activeItinerary}
            tripList={tripList}
            preferredHotels={preferredHotels}
            onSelectPreferredHotel={handleSetPreferredHotel}
            onGenerateItinerary={(config) => {
              saveItineraryToSession(config);
              setActiveItinerary(config);
              setPlannerOpen(false);
              navigate("/itinerary");
            }}
          />

          {/* Non-intrusive PWA Add to Home Screen Prompt */}
          {showPwaPrompt && (
            <PwaInstallPrompt
              deferredPrompt={deferredPrompt}
              onDismiss={() => {
                localStorage.setItem(
                  "heritage_pwa_prompt_dismissed_v1",
                  "true",
                );
                setShowPwaPrompt(false);
              }}
              onInstalled={() => {
                localStorage.setItem(
                  "heritage_pwa_prompt_dismissed_v1",
                  "true",
                );
                setShowPwaPrompt(false);
              }}
            />
          )}
        </div>
      </LanguageProvider>
    </ThemeProvider>
  );
}

frontend/src/components/ProfileDashboard:
import React, { useState, useEffect } from "react";
import { api, useApi, loadItinerary } from "../api";
import { ItineraryConfig } from "./ItineraryView";
import { useLanguage } from "../context/LanguageContext";
import {
  User,
  Mail,
  Lock,
  Calendar,
  DollarSign,
  ChevronRight,
  ArrowRight,
  Building2,
  CheckCircle2,
  AlertCircle,
  SlidersHorizontal,
  LogOut,
  Sparkles,
  MapPin,
  ShieldCheck,
  Check,
  Edit3,
  ExternalLink,
  Plus,
} from "lucide-react";

export interface SavedTrip {
  id: string;
  title: string;
  dates: string;
  daysCount: number;
  totalCost: number;
  planningProgress: number;
  statusLabel: string;
  sitesCount: number;
  sitesList: string[];
  config: ItineraryConfig;
}

interface ProfileDashboardViewProps {
  currentUser: {
    name: string;
    email: string;
    role: "tourist" | "operator";
  } | null;
  onOpenItinerary: (config: ItineraryConfig) => void;
  onOpenExplore: () => void;
  onOpenPlanner: () => void;
  onOpenAdminDashboard?: () => void;
  onLogout: () => void;
}

export const ProfileDashboardView: React.FC<ProfileDashboardViewProps> = ({
  currentUser,
  onOpenItinerary,
  onOpenExplore,
  onOpenPlanner,
  onOpenAdminDashboard,
  onLogout,
}) => {
  const { t } = useLanguage();
  const [role, setRole] = useState<"tourist" | "operator">(
    currentUser?.role || "tourist",
  );

  const [name, setName] = useState<string>(
    currentUser?.name || "Heritage Traveler",
  );
  const [email, setEmail] = useState<string>(
    currentUser?.email || "traveler@heritage.in",
  );

  useEffect(() => {
    if (currentUser) {
      setName(currentUser.name);
      setEmail(currentUser.email);
      setRole(currentUser.role);
    }
  }, [currentUser]);
  const [currentPassword, setCurrentPassword] = useState<string>("");
  const [newPassword, setNewPassword] = useState<string>("");
  const [saveSuccessNotice, setSaveSuccessNotice] = useState<string | null>(
    null,
  );

  const request = useApi(async () => {
    const ids: string[] = JSON.parse(sessionStorage.getItem("heritage_api_trip_ids") || "[]");
    const trips = await Promise.all(ids.map(id => loadItinerary(id)));
    const listings = currentUser?.role === "operator" ? await api.adminList("hotels") : [];
    return {trips:trips.map(({config,result,dto}) => ({id:config.tripId,title:result.activeCity.name,
      dates:dto.trip.created_at,daysCount:config.tripDays,totalCost:result.totalCost,planningProgress:dto.trip.generated_at?100:0,
      statusLabel:dto.trip.generation_summary?.status ?? "Not generated",sitesCount:result.attractionCount,
      sitesList:result.dayPlans.flatMap(d=>d.stops.filter(s=>s.type==="attraction").map(s=>s.name)),config})),
      listings:listings.map(h=>({id:h.id,name:h.name,type:h.stay_type,destination:h.destination_id,
        status:h.provenance_status,lastUpdated:"Not available",price:`?${h.price_per_night} / night`}))};
  }, [currentUser?.email,currentUser?.role]);
  const savedTrips = request.data?.trips ?? [];
  const operatorListings = request.data?.listings ?? [];
  const handleOpenTrip = (trip: SavedTrip) => onOpenItinerary(trip.config);
  const handleSettingsSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSaveSuccessNotice(
      "Account editing is not available from the API yet. No changes were saved.",
    );
    setTimeout(() => {
      setSaveSuccessNotice(null);
    }, 4000);
  };

  const handleDeleteTrip = (tripId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const ids: string[] = JSON.parse(sessionStorage.getItem("heritage_api_trip_ids") || "[]");
    sessionStorage.setItem("heritage_api_trip_ids", JSON.stringify(ids.filter(id => id !== tripId)));
    request.reload();
  };

  if(request.loading) return <p role="status">Loading account records...</p>;
  if(request.error) return <p role="alert">{request.error} <button onClick={request.reload}>Retry</button></p>;
  return (
    <div className="bg-salt min-h-screen py-8 px-4 sm:px-6 lg:px-8 border-b border-stone/30 animate-fadeIn selection:bg-gold selection:text-ink">
      <div className="max-w-5xl mx-auto space-y-10">
        {/* HEADER */}
        <div className="bg-ink text-salt p-6 sm:p-8 border-2 border-gold space-y-4 shadow-lg relative overflow-hidden rounded-2xl">
          <div className="absolute top-0 right-0 w-64 h-64 bg-stepwell-pattern opacity-10 pointer-events-none" />

          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-stone/30 pb-4">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <span className="bg-gold text-ink font-mono text-[11px] uppercase font-bold px-2.5 py-0.5 tracking-wider border border-ink rounded-md">
                  {role === "operator"
                    ? "Registered Tour Operator"
                    : "Heritage Tourist"}
                </span>
                <span className="font-mono text-[10px] text-stone">
                  � Signed-in Account
                </span>
              </div>

              <h1 className="font-display text-2xl sm:text-4xl text-salt font-bold">
                Welcome back, {name || "Traveler"}
              </h1>
            </div>

            <div className="flex flex-wrap items-center gap-2 font-mono text-xs">
              <button
                onClick={() =>
                  setSaveSuccessNotice("Your role is supplied by the authenticated server account.")
                }
                className="bg-salt/10 hover:bg-salt/20 text-gold border border-gold/40 px-3 py-1.5 transition-colors cursor-pointer text-[11px] flex items-center gap-1.5 rounded-lg"
                title="Account role from the authentication server"
              >
                <SlidersHorizontal className="w-3.5 h-3.5 text-gold" />
                <span>
                  View Mode: {role === "tourist" ? "Tourist" : "Operator"}
                </span>
              </button>

              {currentUser && onOpenAdminDashboard && (
                <button
                  onClick={onOpenAdminDashboard}
                  className="bg-gold text-ink hover:bg-gold/90 border border-gold font-bold px-3 py-1.5 transition-colors cursor-pointer text-[11px] flex items-center gap-1.5 rounded-lg"
                >
                  <ShieldCheck className="w-3.5 h-3.5 text-ink" />
                  <span>Admin Panel</span>
                </button>
              )}

              <button
                onClick={onLogout}
                className="bg-madder hover:bg-madder/90 text-salt border border-madder px-3 py-1.5 transition-colors cursor-pointer text-[11px] flex items-center gap-1.5 rounded-lg"
              >
                <LogOut className="w-3.5 h-3.5 text-salt" />
                <span>Log Out</span>
              </button>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-6 font-mono text-xs text-stone">
            <span className="flex items-center gap-1.5">
              <Mail className="w-4 h-4 text-gold" />
              <span>{email}</span>
            </span>
            <span>�</span>
            <span>Saved Routes: {savedTrips.length}</span>
            <span>�</span>
            <span>Account ID: {currentUser?.email}</span>
          </div>
        </div>

        {saveSuccessNotice && (
          <div className="p-3.5 bg-emerald-900 text-salt border-2 border-emerald-400 text-xs font-mono flex items-center gap-2 shadow-md animate-fadeIn rounded-xl">
            <Check className="w-4 h-4 text-emerald-300" />
            <span className="font-bold">{saveSuccessNotice}</span>
          </div>
        )}

        {/* ROLE BASED MAIN VIEW */}
        {role === "tourist" ? (
          <div className="space-y-6">
            <div className="border-b-2 border-gold pb-3 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                  Itinerary Vault
                </span>
                <h2 className="font-display text-xl sm:text-2xl text-charcoal font-bold">
                  My Saved Heritage Trips
                </h2>
              </div>

              <button
                onClick={onOpenPlanner}
                className="inline-flex items-center gap-2 bg-madder hover:bg-madder/90 text-salt text-xs font-mono font-bold px-4 py-2 border border-madder shadow-xs transition-colors cursor-pointer shrink-0 rounded-lg"
              >
                <Plus className="w-4 h-4 text-salt" />
                <span>Create New Heritage Route</span>
              </button>
            </div>

            {savedTrips.length === 0 ? (
              <div className="bg-white border-2 border-dashed border-stone/40 p-8 text-center space-y-4 rounded-2xl">
                <p className="font-mono text-xs text-stone">
                  No saved trips in your heritage ledger.
                </p>
                <button
                  onClick={onOpenPlanner}
                  className="bg-gold text-ink font-mono text-xs font-bold px-4 py-2 border border-ink cursor-pointer rounded-lg shadow-xs"
                >
                  Build Your First Trip
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-1 gap-4">
                {savedTrips.map((trip) => (
                  <div
                    key={trip.id}
                    className="bg-white border-2 border-stone/40 hover:border-gold p-6 transition-all shadow-2xs space-y-4 group rounded-2xl"
                  >
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-stone/20 pb-3">
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="bg-ink text-gold font-mono text-[10px] font-bold px-2 py-0.5 uppercase rounded-md">
                            {trip.dates}
                          </span>
                          <span className="font-mono text-xs text-stone">
                            {trip.daysCount} Days � {trip.sitesCount}{" "}
                            Destinations
                          </span>
                        </div>
                        <h3 className="font-display text-xl text-charcoal font-bold mt-1 group-hover:text-ink transition-colors">
                          {trip.title}
                        </h3>
                      </div>

                      <div className="text-right shrink-0 font-mono">
                        <span className="text-[10px] text-stone uppercase block">
                          Est. Total Outlay
                        </span>
                        <span className="text-lg font-bold text-ink">
                          ?{trip.totalCost.toLocaleString()}
                        </span>
                      </div>
                    </div>

                    <div className="flex flex-wrap items-center justify-between gap-4 font-mono text-xs">
                      <div className="space-y-1 max-w-lg">
                        <span className="text-stone text-[10px] uppercase block">
                          Circuit Destinations:
                        </span>
                        <div className="flex flex-wrap items-center gap-1.5">
                          {trip.sitesList.map((site, i) => (
                            <span
                              key={i}
                              className="bg-salt border border-stone/30 text-charcoal px-2 py-0.5 text-[11px] rounded-md"
                            >
                              {site}
                            </span>
                          ))}
                        </div>
                      </div>

                      <div className="flex items-center gap-2 w-full sm:w-auto justify-end pt-2 sm:pt-0">
                        <button
                          onClick={() => handleOpenTrip(trip)}
                          className="bg-ink hover:bg-ink/90 text-salt border border-gold px-4 py-2 text-xs font-bold cursor-pointer transition-colors flex items-center gap-1.5 shadow-xs rounded-lg"
                        >
                          <span>Open Itinerary</span>
                          <ChevronRight className="w-3.5 h-3.5 text-gold" />
                        </button>

                        <button
                          onClick={(e) => handleDeleteTrip(trip.id, e)}
                          className="bg-salt hover:bg-madder/10 text-stone hover:text-madder border border-stone/30 px-3 py-2 text-xs transition-colors cursor-pointer rounded-lg"
                        >
                          Remove
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ) : (
          /* TOUR OPERATOR DASHBOARD VIEW */
          <div className="space-y-6">
            <div className="border-b-2 border-gold pb-3 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                  Tour Operator Console
                </span>
                <h2 className="font-display text-xl sm:text-2xl text-charcoal font-bold">
                  My Registered Heritage Properties & Stays
                </h2>
              </div>

              <button
                onClick={() =>
                  alert(
                    "New listing application initialized. Tourism guild form submitted.",
                  )
                }
                className="inline-flex items-center gap-2 bg-madder hover:bg-madder/90 text-salt text-xs font-mono font-bold px-4 py-2 border border-madder shadow-xs transition-colors cursor-pointer shrink-0 rounded-lg"
              >
                <Plus className="w-4 h-4 text-salt" />
                <span>Submit New Property for Audit</span>
              </button>
            </div>

            <div className="grid grid-cols-1 gap-4">
              {operatorListings.map((item) => (
                <div
                  key={item.id}
                  className="bg-white border-2 border-stone/40 p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 font-mono text-xs rounded-2xl shadow-xs"
                >
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <Building2 className="w-4 h-4 text-gold shrink-0" />
                      <span className="font-bold text-charcoal text-sm">
                        {item.name}
                      </span>
                      <span className="bg-salt text-charcoal border border-stone/40 text-[10px] px-2 py-0.5 uppercase rounded-md">
                        {item.type}
                      </span>
                    </div>
                    <p className="text-stone text-[11px]">
                      Destination: {item.destination} � Status:{" "}
                      <strong className="text-emerald-800">
                        {item.status}
                      </strong>
                    </p>
                  </div>

                  <div className="flex items-center gap-3 shrink-0 self-end sm:self-auto">
                    <span className="font-bold text-ink text-sm">
                      {item.price}
                    </span>
                    <button
                      onClick={() => alert(`Editing listing "${item.name}"...`)}
                      className="bg-salt hover:bg-stone/20 text-charcoal border border-stone/40 px-3 py-1.5 cursor-pointer flex items-center gap-1 rounded-lg"
                    >
                      <Edit3 className="w-3.5 h-3.5 text-ink" />
                      <span>Edit</span>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ACCOUNT SETTINGS FORM */}
        <div className="bg-white border-2 border-stone/40 p-6 sm:p-8 space-y-6 shadow-2xs rounded-2xl">
          <div className="border-b border-stone/30 pb-3">
            <span className="font-mono text-xs text-gold uppercase tracking-widest block">
              Security & Credentials
            </span>
            <h2 className="font-display text-xl text-charcoal font-bold">
              Account Preferences
            </h2>
          </div>

          <form
            onSubmit={handleSettingsSubmit}
            className="space-y-5 max-w-2xl font-mono text-xs"
          >
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="block text-charcoal uppercase tracking-wider text-[11px] font-bold">
                  Full Name / Title
                </label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full p-2.5 bg-salt border border-stone/40 text-charcoal text-sm outline-none focus:border-gold rounded-lg"
                  required
                />
              </div>

              <div className="space-y-1.5">
                <label className="block text-charcoal uppercase tracking-wider text-[11px] font-bold">
                  Email Address
                </label>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full p-2.5 bg-salt border border-stone/40 text-charcoal text-sm outline-none focus:border-gold rounded-lg"
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
              <div className="space-y-1.5">
                <label className="block text-charcoal uppercase tracking-wider text-[11px] font-bold">
                  Current Password
                </label>
                <input
                  type="password"
                  placeholder="������������"
                  value={currentPassword}
