} from "lucide-react";

export interface ItineraryConfig {
  tripId?: string;
  cityId: string;
  tripDays: number;
  budget: number;
  startingHotelId?: string;
  startTime?: string;
  selectedSites?: string[];
  strategy?: OptimizationStrategy;
  wheelchairAccessibleOnly?: boolean;
}

interface ItineraryViewProps {
  config: ItineraryConfig;
  onPersistedConfig?: (config: ItineraryConfig) => void;
  preferredHotels?: Record<string, string>;
  onSelectPreferredHotel?: (cityId: string, hotelId: string) => void;
  onBackToPlanner: () => void;
  onSelectDestination?: (dest: Destination) => void;
  onOpenBudgetPlanner?: () => void;
  isReadOnly?: boolean;
  onPlanOwnTrip?: () => void;
}

interface ItineraryStop {
  id: string;
  type: "hotel" | "attraction" | "meal" | "transit";
  name: string;
  category: string;
  arrivalTime: string;
  departureTime: string;
  durationMinutes: number;
  cost: number;
  location: string;
  imageUrl?: string;
  description?: string;
  lat?: number;
  lng?: number;
}

interface DayRoute {
  dayNumber: number;
  dateLabel: string;
  title: string;
  stops: ItineraryStop[];
  totalKm: number;
  totalCost: number;
}

function formatTime(minutesFromMidnight: number): string {
  const mins = Math.floor(minutesFromMidnight) % (24 * 60);
  const hours = Math.floor(mins / 60);
  const m = mins % 60;
  const ampm = hours >= 12 ? "PM" : "AM";
  const displayHours = hours % 12 === 0 ? 12 : hours % 12;
  const displayMins = m < 10 ? `0${m}` : m;
  return `${displayHours}:${displayMins} ${ampm}`;
}

function parseTimeToMinutes(timeStr?: string): number {
  if (!timeStr) return 8 * 60;
  const parts = timeStr.trim().split(" ");
  if (parts.length < 2) return 8 * 60;
  const [hStr, mStr] = parts[0].split(":");
  let hours = parseInt(hStr, 10) || 8;
  const mins = parseInt(mStr, 10) || 0;
  const ampm = parts[1].toUpperCase();
  if (ampm === "PM" && hours < 12) hours += 12;
  if (ampm === "AM" && hours === 12) hours = 0;
  return hours * 60 + mins;
}

export const ItineraryView: React.FC<ItineraryViewProps> = ({
  config,
  onPersistedConfig,
  preferredHotels,
  onSelectPreferredHotel,
  onBackToPlanner,
  onSelectDestination,
  onOpenBudgetPlanner,
  isReadOnly = false,
  onPlanOwnTrip,
}) => {
  const { language, t, getName } = useLanguage();

  const [showAlgorithm, setShowAlgorithm] = useState<boolean>(false);
  const [savedShareNotice, setSavedShareNotice] = useState<boolean>(false);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState<boolean>(false);
  const [showComparisonModal, setShowComparisonModal] =
    useState<boolean>(false);
  const [isShareModalOpen, setIsShareModalOpen] = useState<boolean>(false);

  const pdfContainerRef = useRef<HTMLDivElement>(null);

  const [activeConfig, setActiveConfig] = useState<ItineraryConfig>(config);
  const [isWhatIfOpen, setIsWhatIfOpen] = useState<boolean>(false);
  const [sliderBudget, setSliderBudget] = useState<number>(
    config.budget || 8500,
  );
  const [sliderDays, setSliderDays] = useState<number>(config.tripDays || 2);
  const [debouncedBudget, setDebouncedBudget] = useState<number>(
    config.budget || 8500,
  );
  const [debouncedDays, setDebouncedDays] = useState<number>(
    config.tripDays || 2,
  );
  const [isSavedWhatIfNotice, setIsSavedWhatIfNotice] =
    useState<boolean>(false);

  useEffect(() => {
    setActiveConfig(config);
    setSliderBudget(config.budget || 8500);
    setSliderDays(config.tripDays || 2);
    setDebouncedBudget(config.budget || 8500);
    setDebouncedDays(config.tripDays || 2);
  }, [config]);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedBudget(sliderBudget);
      setDebouncedDays(sliderDays);
    }, 300);
    return () => clearTimeout(handler);
  }, [sliderBudget, sliderDays]);

  const activeStrategy =
    activeConfig.strategy || config.strategy || "distance-first";

  const request = useApi(signal => loadItinerary(activeConfig.tripId ?? "", signal), [activeConfig.tripId]);
  const [pendingSave, setPendingSave] = useState(false);
  const [saveError, setSaveError] = useState("");
  // All hooks above the loading boundary; stale rows never render while reloading.
  if(request.loading || pendingSave) return <p role="status">Loading persisted itinerary...</p>;
  if(request.error || !request.data) return <p role="alert">{request.error || "No persisted itinerary available."} <button onClick={request.reload}>Retry</button> <button onClick={onBackToPlanner}>Open planner</button></p>;
  const generatedResult = request.data.result;
  const baselineResult = generatedResult;
  const activeResult = generatedResult;
  const liveResult = generatedResult;
  const activeCity = generatedResult.activeCity;
  const cityName = getName(activeCity);
  const preferredHotelId = activeConfig.startingHotelId;
  const currentCity = activeCity;
  const currentCityName = cityName;
  const tripTitle = `${currentCityName} Circular Heritage Circuit`;

  const handleSaveWhatIfVersion = async () => {
    setPendingSave(true); setSaveError("");
    try {
      const saved = await createItinerary({...request.data.config,budget:debouncedBudget,tripDays:debouncedDays});
      setActiveConfig(saved.config); onPersistedConfig?.(saved.config);
      setIsSavedWhatIfNotice(true); setIsWhatIfOpen(false);
    } catch(error) { setSaveError(errorMessage(error)); }
    finally { setPendingSave(false); }
  };

  const handleResetWhatIf = () => {
    setActiveConfig(config);
    setSliderBudget(config.budget || 8500);
    setSliderDays(config.tripDays || 2);
    setDebouncedBudget(config.budget || 8500);
    setDebouncedDays(config.tripDays || 2);
  };

  const numDays = request.data.dto.trip.trip_days;
  const dayPlans = generatedResult.dayPlans;
  const startingHotel = generatedResult.startingHotel;
  const totalDistanceKm = generatedResult.totalDistanceKm;
  const estimatedTotalCost = generatedResult.totalCost;

  const totalHotelCost = generatedResult.hotelTotalCost ?? ((startingHotel.priceNumeric || 0) * numDays);
  const totalAttractionCost = generatedResult.attractionTotalCost ?? dayPlans.reduce(
    (acc, d) =>
      acc +
      d.stops
        .filter((s) => s.type === "attraction")
        .reduce((a, s) => a + s.cost, 0),
    0,
  );
  const totalMealCost = generatedResult.mealTotalCost ?? dayPlans.reduce(
    (acc, d) =>
      acc +
      d.stops.filter((s) => s.type === "meal").reduce((a, s) => a + s.cost, 0),
    0,
  );
  const totalTransitCost = generatedResult.transitTotalCost ?? 0;

  const handleDownloadPdf = async () => {
    if (!pdfContainerRef.current) return;
    setIsGeneratingPdf(true);
    try {
      const [jspdfModule, html2canvasModule] = await Promise.all([
        import("jspdf"),
        import("html2canvas"),
      ]);
      const jsPDF = jspdfModule.default || jspdfModule.jsPDF || (jspdfModule as any);
      const html2canvas = html2canvasModule.default || (html2canvasModule as any);

      const element = pdfContainerRef.current;
      let canvas: HTMLCanvasElement;
      try {
        canvas = await html2canvas(element, {
          scale: 2,
          useCORS: true,
          allowTaint: true,
          logging: false,
          backgroundColor: "#FFFFFF",
          scrollX: 0,
          scrollY: 0,
          windowWidth: element.scrollWidth || document.documentElement.offsetWidth,
          windowHeight: element.scrollHeight,
        });
      } catch (e: any) {
        // Fallback to dom-to-image-more for okLab colour support
        const domToImageModule = await import("dom-to-image-more");
        const domToImage = domToImageModule.default || domToImageModule;
        const dataUrl = await domToImage.toJpeg(element, { quality: 0.95 });
        const img = new Image();
        await new Promise<void>((resolve, reject) => {
          img.onload = () => resolve();
          img.onerror = reject;
          img.src = dataUrl;
        });
        canvas = document.createElement("canvas");
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext("2d");
        if (!ctx) throw new Error("Canvas context unavailable");
        ctx.drawImage(img, 0, 0);
      }

      const imgData = canvas.toDataURL("image/jpeg", 0.95);
      const pdf = new jsPDF("p", "mm", "a4");
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = pdf.internal.pageSize.getHeight();
      const imgWidth = pdfWidth;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      let heightLeft = imgHeight;
      let position = 0;

      pdf.addImage(imgData, "JPEG", 0, position, imgWidth, imgHeight);
      heightLeft -= pdfHeight;

      while (heightLeft > 0) {
        position -= pdfHeight;
        pdf.addPage();
        pdf.addImage(imgData, "JPEG", 0, position, imgWidth, imgHeight);
        heightLeft -= pdfHeight;
      }

      const sanitizeName = (tripTitle || "gujarat-heritage")
        .toLowerCase()
        .replace(/[^a-z0-9]/g, "-")
        .replace(/-+/g, "-");
      pdf.save(`${sanitizeName}-itinerary.pdf`);
    } catch (err) {
      console.error("Error generating itinerary PDF:", err);
      window.print();
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  const isPreferredBase = preferredHotelId === startingHotel.id;

  const handlePrint = () => window.print();
  const handleShare = () => {
    setIsShareModalOpen(true);
  };

  return (
    <div className="bg-salt min-h-screen py-8 px-4 sm:px-6 lg:px-8 border-b border-stone/30 animate-fadeIn selection:bg-gold selection:text-ink">
      <div className="max-w-7xl mx-auto space-y-8">
        {saveError && <p role="alert">{saveError}</p>}
      {generatedResult.warning && <p role="status">{generatedResult.warning}</p>}
      {isWhatIfOpen && <p role="status">Showing the saved itinerary. Save the new parameters to generate a server-backed version.</p>}
      {/* Read-Only Shared Itinerary Banner */}
        {isReadOnly && (
          <div className="bg-ink border-2 border-gold p-4 text-salt flex flex-wrap items-center justify-between gap-4 shadow-md font-mono no-print">
            <div className="flex items-center gap-3">
              <span className="inline-block w-2.5 h-2.5 bg-gold rounded-full animate-pulse shrink-0" />
              <div>
                <span className="text-gold font-bold uppercase tracking-wider text-[10px] block">
                  Read-Only View
                </span>
                <span className="text-sm font-sans font-medium text-salt">
                  Shared itinerary for{" "}
                  <strong className="text-gold font-bold">{cityName}</strong> �
                  viewing only
                </span>
              </div>
            </div>
            <button
              onClick={onPlanOwnTrip || onBackToPlanner}
              className="bg-madder hover:bg-madder/90 text-salt border border-madder text-xs font-mono font-bold px-4 py-2 transition-colors shadow-xs cursor-pointer flex items-center gap-2"
            >
              <Sparkles className="w-3.5 h-3.5 text-salt" />
              <span>Plan your own trip</span>
            </button>
          </div>
        )}

        {/* Top Control Bar: Back / Actions */}
        <div className="flex flex-wrap items-center justify-between gap-4 border-b border-stone/30 pb-4 no-print">
          <div className="flex items-center gap-3">
            {!isReadOnly && (
              <>
                <button
                  onClick={onBackToPlanner}
                  className="inline-flex items-center gap-2 bg-stone/20 hover:bg-stone/30 text-charcoal border border-stone/40 text-xs font-mono px-4 py-2 transition-colors cursor-pointer rounded-lg"
                >
                  <SlidersHorizontal className="w-3.5 h-3.5 text-ink" />
                  <span>
                    {language === "hi"
                      ? "????? ??? ????? ????"
                      : "Adjust plan"}
                  </span>
                </button>

                <button
                  type="button"
                  onClick={() => setIsWhatIfOpen(!isWhatIfOpen)}
                  className={`inline-flex items-center gap-2 border text-xs font-mono font-bold px-4 py-2 transition-colors cursor-pointer rounded-lg ${
                    isWhatIfOpen
                      ? "bg-gold text-ink border-gold shadow-xs"
                      : "bg-salt hover:bg-gold/10 text-charcoal border-gold/70"
                  }`}
                >
                  <Sparkles
                    className={`w-3.5 h-3.5 ${isWhatIfOpen ? "text-ink" : "text-gold"}`}
                  />
                  <span>What if?</span>
                  {isWhatIfOpen ? (
                    <ChevronUp className="w-3.5 h-3.5" />
                  ) : (
                    <ChevronDown className="w-3.5 h-3.5" />
                  )}
                </button>
              </>
            )}

            <button
              onClick={() => {
                if (onOpenBudgetPlanner) {
                  onOpenBudgetPlanner();
                }
              }}
              className="inline-flex items-center gap-2 bg-madder hover:bg-madder/90 text-salt border border-madder text-xs font-mono font-bold px-4 py-2 transition-colors shadow-xs cursor-pointer rounded-lg"
            >
              <DollarSign className="w-3.5 h-3.5 text-salt" />
              <span>
                {language === "hi"
                  ? "??? ?????"
                  : "View budget breakdown"}
              </span>
            </button>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={handleShare}
              className="inline-flex items-center gap-1.5 bg-salt border border-stone/40 hover:border-gold text-charcoal text-xs font-mono px-3 py-2 transition-colors cursor-pointer rounded-lg"
            >
              <Share2 className="w-3.5 h-3.5 text-gold" />
              <span>
                {language === "hi"
                  ? "???? ????"
                  : "Share Route"}
              </span>
            </button>

            <button
              onClick={handlePrint}
              className="inline-flex items-center gap-1.5 bg-salt border border-stone/40 hover:border-gold text-charcoal text-xs font-mono px-3 py-2 transition-colors cursor-pointer rounded-lg"
            >
              <Printer className="w-3.5 h-3.5 text-gold" />
              <span>
                {language === "hi"
                  ? "?????? ????"
                  : "Print Ledger"}
              </span>
            </button>

            <button
              onClick={handleDownloadPdf}
              disabled={isGeneratingPdf}
              aria-label="Download PDF Itinerary"
              className="inline-flex items-center gap-1.5 bg-ink text-salt border border-gold hover:bg-ink/90 text-xs font-mono font-bold px-3.5 py-2 transition-colors cursor-pointer disabled:opacity-50 shadow-xs rounded-lg"
            >
              {isGeneratingPdf ? (
                <>
                  <Loader2 className="w-3.5 h-3.5 text-gold animate-spin" />
                  <span>PDF...</span>
                </>
              ) : (
                <>
                  <Download className="w-3.5 h-3.5 text-gold" />
                  <span>Download PDF</span>
                </>
              )}
            </button>
          </div>
        </div>

        {/* Collapsible "What if?" Live Scenario Panel */}
        {isWhatIfOpen && (
          <WhatIfPanel
            currentBudget={activeConfig.budget || 8500}
            currentDays={activeConfig.tripDays || 2}
            originalBudget={config.budget || 8500}
            originalDays={config.tripDays || 2}
            sliderBudget={sliderBudget}
            sliderDays={sliderDays}
            onBudgetChange={setSliderBudget}
            onDaysChange={setSliderDays}
            liveAttractionCount={liveResult.attractionCount}
            baselineAttractionCount={baselineResult.attractionCount}
            liveCost={liveResult.totalCost}
            baselineCost={baselineResult.totalCost}
            onReset={handleResetWhatIf}
            onSaveVersion={handleSaveWhatIfVersion}
            isSavedNotice={isSavedWhatIfNotice}
          />
        )}

        {savedShareNotice && (
          <div className="p-3 bg-emerald-900 text-salt border border-emerald-500 text-xs font-mono flex items-center gap-2 animate-fadeIn">
            <Check className="w-4 h-4 text-emerald-300" />
            <span>Itinerary route link copied to clipboard!</span>
          </div>
        )}

        {/* Printable Container */}
        <div
          ref={pdfContainerRef}
          id="printable-itinerary"
          className="printable-content space-y-8 bg-salt p-2 sm:p-4 border border-stone/20"
        >
          {/* Header Banner */}
          <div className="itinerary-header-banner bg-ink text-salt p-6 sm:p-8 border-2 border-gold space-y-6 relative overflow-hidden shadow-lg rounded-2xl">
            <div className="absolute inset-0 bg-stepwell-pattern opacity-10 pointer-events-none" />

            <div className="relative z-10 space-y-4">
              <div className="flex items-center gap-2 font-mono text-[11px] uppercase tracking-widest text-gold">
                <Compass className="w-4 h-4 text-gold" />
                <span>Intra-City Circular Route Plan � {currentCityName}</span>
              </div>

              <h1 className="font-display text-2xl sm:text-4xl text-salt font-bold">
                {tripTitle}
              </h1>

              <div className="flex flex-wrap items-center gap-4 text-xs font-mono text-stone pt-2 border-t border-stone/30">
                <span className="flex items-center gap-1.5 text-salt font-bold">
                  <MapPin className="w-4 h-4 text-gold" />
                  City: {currentCityName}
                </span>
                <span className="flex items-center gap-1.5">
                  <HotelIcon className="w-4 h-4 text-gold" />
                  <span>
                    Base Hotel: <strong>{startingHotel.name}</strong>
                  </span>
                  {isPreferredBase && (
                    <span className="bg-gold text-ink font-bold text-[10px] px-1.5 py-0.5 border border-gold uppercase rounded">
                      ? Preferred Stay
                    </span>
                  )}
                </span>
                <span className="flex items-center gap-1.5">
                  <Clock className="w-4 h-4 text-gold" />
                  Start Time: {config.startTime || "08:00 AM"}
                </span>
                <span className="flex items-center gap-1.5 text-gold font-bold">
                  <RotateCcw className="w-4 h-4 text-gold" />
                  Circular Route (Hotel ? Attractions ? Meals ? Hotel)
                </span>
              </div>
            </div>
          </div>

          {/* Hotel Constraint Adjustment Notice (Non-Silent Replacement Explanation) */}
          {generatedResult.hotelReplacementNotice && (
            <div className="bg-amber-950/85 text-salt border-2 border-amber-500 p-4 font-mono text-xs flex items-start gap-3 shadow-lg animate-fadeIn no-print rounded-xl">
              <AlertTriangle className="w-5 h-5 text-amber-400 shrink-0 mt-0.5" />
              <div>
                <div className="text-amber-300 font-bold uppercase tracking-wider mb-1">
                  Selected Hotel Adjusted Due to Constraint
                </div>
                <p className="text-amber-100/90 leading-relaxed">
                  {generatedResult.hotelReplacementNotice}
                </p>
              </div>
            </div>
          )}

          {/* Empty / Error State when no valid route combination exists */}
          {generatedResult.hasNoCompatibleAttractions ? (
            <div className="bg-ink text-salt p-8 sm:p-12 border-2 border-madder text-center space-y-5 my-6 shadow-2xl animate-fadeIn rounded-2xl">
              <div className="inline-flex p-4 bg-madder/20 border border-madder rounded-full">
                <AlertTriangle className="w-10 h-10 text-madder" />
              </div>
              <div className="space-y-2 max-w-lg mx-auto">
                <h2 className="font-display text-2xl sm:text-3xl font-bold text-salt">
                  {config.wheelchairAccessibleOnly
                    ? "No Wheelchair-Accessible Itinerary Found"
                    : "No Compatible Heritage Route"}
                </h2>
                <p className="font-sans text-sm text-stone leading-relaxed">
                  {generatedResult.emptyStateReason ||
                    "No attractions could be scheduled with the current constraint combination."}
                </p>
              </div>
              <div className="pt-4 flex flex-wrap justify-center gap-3">
                <button
                  type="button"
                  onClick={onBackToPlanner}
                  className="bg-gold hover:bg-gold/90 text-ink font-mono font-bold text-xs px-6 py-3 uppercase tracking-wider transition-colors cursor-pointer shadow-md"
                >
                  Adjust Constraints in Planner
                </button>
                {onPlanOwnTrip && (
                  <button
                    type="button"
                    onClick={onPlanOwnTrip}
                    className="bg-stone/20 hover:bg-stone/30 text-salt border border-stone/40 font-mono text-xs px-5 py-3 uppercase tracking-wider transition-colors cursor-pointer"
                  >
                    Explore All Destinations
                  </button>
                )}
              </div>
            </div>
          ) : (
            <>
              {/* Remote & Wildlife Destination Facility Callout */}
              {["gir", "rann-of-kutch", "saputara"].includes(activeCity.id) &&
                (activeCity.nearestHospital || activeCity.nearestPoliceStation) && (
                  <div className="bg-salt border border-stone/30 p-4 font-mono text-xs text-stone space-y-2 shadow-xs">
                    <div className="flex items-center gap-2 text-charcoal font-bold text-[11px] uppercase tracking-wider">
                      <Shield className="w-4 h-4 text-gold shrink-0" />
                      <span>
                        Travel Preparation Note � {currentCityName} Remote Sector
                      </span>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-[11px] text-stone">
                      {activeCity.nearestHospital && (
                        <div className="flex items-center gap-2 bg-white p-2 border border-stone/20">
                          <Hospital className="w-3.5 h-3.5 text-emerald-800 shrink-0" />
                          <span>
                            <strong>Nearest hospital:</strong>{" "}
                            {activeCity.nearestHospital} (from your starting hotel)
                          </span>
                        </div>
                      )}
                      {activeCity.nearestPoliceStation && (
                        <div className="flex items-center gap-2 bg-white p-2 border border-stone/20">
                          <Shield className="w-3.5 h-3.5 text-stone shrink-0" />
                          <span>
                            <strong>Nearest police station:</strong>{" "}
                            {activeCity.nearestPoliceStation}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                )}

          {/* Slim Collapsible Algorithm Execution Stats Strip */}
          {generatedResult.stats && (
            <div className="no-print">
              <AlgorithmStatsPanel
                stats={generatedResult.stats}
                collapsible={true}
                defaultExpanded={false}
                title="View algorithm stats"
              />
            </div>
          )}

          {/* Graceful Offline Circular Route Map Circuit */}
          <div className="no-print">
            <OfflineRouteMap
              dayPlans={dayPlans}
              cityName={cityName}
              startingHotelName={startingHotel.name}
              totalDistanceKm={totalDistanceKm}
              isOffline={
                typeof navigator !== "undefined" ? !navigator.onLine : false
              }
            />
          </div>

          {/* Dijkstra Supporting Algorithm Visualizer Accordion */}
          <div className="border-2 border-gold bg-white p-4 space-y-3 no-print rounded-xl">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 font-mono text-xs text-ink font-bold">
                <Cpu className="w-4 h-4 text-gold" />
                <span>Intra-City Shortest Path Visualizer</span>
              </div>
              <button
                onClick={() => setShowAlgorithm(!showAlgorithm)}
                className="bg-salt hover:bg-stone/20 text-charcoal border border-stone/40 font-mono text-xs font-bold px-3 py-1 flex items-center gap-1 cursor-pointer rounded-md"
              >
                <span>
                  {showAlgorithm ? "Hide Visualizer" : "Expand Visualizer"}
                </span>
                {showAlgorithm ? (
                  <ChevronUp className="w-4 h-4" />
                ) : (
                  <ChevronDown className="w-4 h-4" />
                )}
              </button>
            </div>

            <p className="font-mono text-xs text-stone italic border-l-2 border-gold pl-2">
              "Dijkstra finds the shortest path between two attractions when
              they aren't directly connected -- most stops in your route are
              direct, this shows what happens when one isn't."
            </p>

            {showAlgorithm && (
              <div className="pt-3 border-t border-stone/30 animate-fadeIn">
                <DijkstraVisualizer cityId={activeCity.id} tripId={activeConfig.tripId} />
              </div>
            )}
          </div>

          {/* Day-by-Day Circular Itinerary Cards */}
          <div className="space-y-8">
            <AnimatePresence mode="popLayout">
              {dayPlans.map((day, dayIdx) => (
                <motion.div
                  key={`day-${day.dayNumber}`}
                  layout
                  initial={{ opacity: 0, y: 15 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -15 }}
                  transition={{ duration: 0.3, delay: dayIdx * 0.05 }}
                  className="itinerary-day-card bg-white border-2 border-stone/40 p-5 sm:p-6 space-y-6 shadow-sm rounded-xl"
                >
                  {/* Day Header */}
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b-2 border-gold pb-3">
                    <div>
                      <span className="bg-ink text-gold font-mono text-xs font-bold px-2.5 py-1 uppercase tracking-wider rounded-md">
                        {day.dateLabel}
                      </span>
                      <h3 className="font-display text-xl sm:text-2xl text-ink font-bold mt-1">
                        {day.title}
                      </h3>
                    </div>

                    <div className="flex items-center gap-3 font-mono text-xs text-stone">
                      <span>{day.totalKm} km local circuit</span>
                      <span className="font-bold text-ink">
                        Est. Day Cost: ?{displayNumber(day.totalCost)}
                      </span>
                    </div>
                  </div>

                  {/* Circular Timed Stops List */}
                  <div className="space-y-4">
                    <AnimatePresence mode="popLayout">
                      {day.stops.map((stop, idx) => {
                        const stopNumber = idx + 1;
                        const isFinalStop = idx === day.stops.length - 1;

                        const accessibleLabel =
                          stop.type === "meal"
                            ? `Stop ${stopNumber} of ${day.stops.length}: Lunch break at ${stop.name}, arrive ${stop.arrivalTime}, depart ${stop.departureTime}, duration ${stop.durationMinutes} minutes, estimated cost ?${displayNumber(stop.cost)}`
                            : stop.type === "hotel"
                              ? isFinalStop
                                ? `Stop ${stopNumber} of ${day.stops.length} (Final Stop): Return to ${stop.name}, arrive ${stop.arrivalTime}, depart ${stop.departureTime}, completing circular route`
                                : `Stop ${stopNumber} of ${day.stops.length} (Start): Depart ${stop.name}, depart at ${stop.departureTime}`
                              : `Stop ${stopNumber} of ${day.stops.length}: ${stop.name}, ${stop.category}, arrive ${stop.arrivalTime}, depart ${stop.departureTime}, duration ${stop.durationMinutes} minutes, cost ${stop.cost > 0 ? "?" + displayNumber(stop.cost) : "Free"}`;

                        return (
                          <motion.div
                            key={stop.id}
                            layout
                            initial={{ opacity: 0, x: -12, scale: 0.98 }}
                            animate={{ opacity: 1, x: 0, scale: 1 }}
                            exit={{ opacity: 0, x: 12, scale: 0.98 }}
                            transition={{ duration: 0.25, delay: idx * 0.03 }}
                            tabIndex={0}
                            aria-label={accessibleLabel}
                            className={`itinerary-stop-card p-4 border text-xs font-mono transition-colors flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 focus:outline-none focus:ring-2 focus:ring-gold rounded-xl ${
                              stop.type === "meal"
                                ? "bg-amber-50/70 border-gold/80"
                                : stop.type === "hotel"
                                  ? "bg-salt border-stone/40"
                                  : stop.type === "transit"
                                    ? "bg-sky-50 border-sky-300"
                                    : "bg-white border-stone/30 hover:border-gold"
                            }`}
                          >
                            {(() => {
                              const conflict =
                                stop.type === "attraction"
                                  ? checkBestTimeConflict(
                                      stop.arrivalTime,
                                      stop.bestTimeNote,
                                    )
                                  : { hasConflict: false, warningMessage: "" };

                              return (
                                <div className="flex items-start gap-3 w-full sm:w-auto">
                                  {/* Stop Photo Thumbnail if available */}
                                  {stop.imageUrl && (
                                    <div className="w-14 h-14 sm:w-16 sm:h-16 shrink-0 overflow-hidden border border-stone/30 bg-charcoal rounded-lg">
                                      <ImageWithFallback
                                        src={stop.imageUrl}
                                        alt={stop.name}
                                        category={stop.category}
                                        className="w-full h-full object-cover hover:scale-105 transition-transform duration-300 rounded-lg"
                                      />
                                    </div>
                                  )}

                                  {/* Stop Number Badge */}
                                  <div className="bg-gold text-ink font-bold px-2 py-1 text-[11px] border border-ink shrink-0 text-center rounded-md">
                                    <span>#{stopNumber}</span>
                                  </div>

                                  {/* Timed Badge */}
                                  <div className="bg-ink text-salt px-2.5 py-1 text-[11px] font-bold border border-gold shrink-0 text-center rounded-md">
                                    <span className="block text-gold text-[10px] uppercase">
                                      Arrival - Depart
                                    </span>
                                    <span>
                                      {stop.arrivalTime} - {stop.departureTime}
                                    </span>
                                  </div>

                                  {/* Stop Icon & Description */}
                                  <div className="flex-1 min-w-0">
                                    <div className="flex flex-wrap items-center gap-2 font-bold text-sm text-ink">
                                      {stop.type === "meal" ? (
                                        <>
                                          <Utensils className="w-4 h-4 text-gold shrink-0" />
                                          <span className="bg-gold/20 text-ink px-1.5 py-0.5 text-[10px] uppercase font-mono border border-gold/40">
                                            Meal Break
                                          </span>
                                        </>
                                      ) : stop.type === "hotel" ? (
                                        <HotelIcon className="w-4 h-4 text-ink shrink-0" />
                                      ) : stop.type === "transit" ? (
                                        <>
                                          <Ship className="w-4 h-4 text-sky-700 shrink-0" />
                                          <span className="bg-sky-100 text-sky-800 px-1.5 py-0.5 text-[10px] uppercase font-mono border border-sky-300">
                                            Ferry Crossing
                                          </span>
                                        </>
                                      ) : (
                                        <Ticket className="w-4 h-4 text-madder shrink-0" />
                                      )}
                                      <span>{stop.name}</span>
                                      {conflict.hasConflict && (
                                        <span
                                          className="inline-flex items-center gap-1 bg-amber-100 text-amber-950 border border-amber-400 px-2 py-0.5 text-[10px] font-mono font-bold shrink-0 cursor-help"
                                          title={conflict.warningMessage}
                                        >
                                          <AlertTriangle className="w-3.5 h-3.5 text-amber-700 shrink-0" />
                                          <span>Time Mismatch</span>
                                        </span>
                                      )}
                                    </div>

                                    {stop.type === "attraction" &&
                                      stop.bestTimeNote && (
                                        <div className="mt-1">
                                          <BestTimeNote
                                            note={stop.bestTimeNote}
                                          />
                                        </div>
                                      )}

                                    {conflict.hasConflict && (
                                      <p className="text-[11px] text-amber-900 bg-amber-50 border border-amber-300 px-2.5 py-1 mt-1.5 font-mono flex items-center gap-1.5">
                                        <AlertTriangle className="w-3.5 h-3.5 text-amber-700 shrink-0" />
                                        <span>{conflict.warningMessage}</span>
                                      </p>
                                    )}

                                    <p className="text-stone text-[11px] mt-1">
                                      {stop.description}
                                    </p>
                                    <span className="text-[10px] text-stone/80 uppercase tracking-wider block mt-1">
                                      {stop.category} � {stop.location}
                                    </span>
                                    {stop.type === "attraction" &&
                                      (stop.wheelchairAccessible !==
                                        undefined ||
                                        stop.physicalDemand) && (
                                        <div className="mt-1.5">
                                          <AccessibilityBadge
                                            wheelchairAccessible={
                                              stop.wheelchairAccessible
                                            }
                                            physicalDemand={stop.physicalDemand}
                                          />
                                        </div>
                                      )}
                                  </div>
                                </div>
                              );
                            })()}

                            {/* Cost & Duration */}
                            <div className="text-right shrink-0 self-end sm:self-auto border-t sm:border-t-0 pt-2 sm:pt-0 border-stone/20 w-full sm:w-auto flex sm:flex-col justify-between items-center sm:items-end">
                              <span className="font-bold text-ink text-sm">
                                {stop.cost > 0
                                  ? `?${displayNumber(stop.cost)}`
                                  : "Free / Included"}
                              </span>
                              <span className="text-[10px] text-stone">
                                Duration: {stop.durationMinutes} mins
                              </span>
                            </div>
                          </motion.div>
                        );
                      })}
                    </AnimatePresence>
                  </div>

                  {/* Day Summary Loop Banner */}
                  <div className="p-3 bg-salt border border-stone/30 font-mono text-xs flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2 text-stone rounded-lg">
                    <span className="flex items-center gap-1.5 text-ink font-bold">
                      <span>Circular Route Loop:</span>
                      <span className="font-normal text-stone">
                        Start at {startingHotel.name} ? {day.stops.length - 2}{" "}
                        Stops ? Return to {startingHotel.name}
                      </span>
                    </span>
                    <span className="font-bold text-ink shrink-0">
                      {day.stops.length} Timed Stops Complete
                    </span>
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>

              {/* Overall Budget Summary Card */}
              <div className="budget-summary-card bg-ink text-salt p-6 border-2 border-gold space-y-4 rounded-2xl">
                <h4 className="font-display text-xl text-gold font-bold border-b border-stone/30 pb-2">
                  {currentCityName} Circuit Budget Breakdown
                </h4>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 font-mono text-xs">
                  <div className="p-3 bg-salt/10 border border-stone/30 rounded-xl">
                    <span className="text-stone text-[10px] uppercase block">
                      Hotels ({numDays} Nights)
                    </span>
                    <span className="font-bold text-salt text-sm">
                      ?{displayNumber(totalHotelCost)}
                    </span>
                  </div>
                  <div className="p-3 bg-salt/10 border border-stone/30 rounded-xl">
                    <span className="text-stone text-[10px] uppercase block">
                      Attraction Entry Fees
                    </span>
                    <span className="font-bold text-salt text-sm">
                      ?{displayNumber(totalAttractionCost)}
                    </span>
                  </div>
                  <div className="p-3 bg-salt/10 border border-stone/30 rounded-xl">
                    <span className="text-stone text-[10px] uppercase block">
                      Meals & Dining
                    </span>
                    <span className="font-bold text-gold text-sm">
                      ?{displayNumber(totalMealCost)}
                    </span>
                  </div>
                  <div className="p-3 bg-salt/10 border border-stone/30 rounded-xl">
                    <span className="text-stone text-[10px] uppercase block">
                      Transit & Ferry
                    </span>
                    <span className="font-bold text-salt text-sm">
                      {totalTransitCost > 0
                        ? `?${displayNumber(totalTransitCost)}`
                        : "Included (?0)"}
                    </span>
                  </div>
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-stone/30 font-mono text-sm">
                  <span className="text-stone">Estimated Total Outlay:</span>
                  <span className="font-bold text-gold text-lg">
                    ?{displayNumber(estimatedTotalCost)}
                  </span>
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Share Itinerary Modal */}
      <ShareItineraryModal
        config={activeConfig}
        cityName={cityName}
        isOpen={isShareModalOpen}
        onClose={() => setIsShareModalOpen(false)}
      />
    </div>
  );
};

frontend/src/components/HotelsView.tsx:
import { displayNumber } from "../api";
import React, { useState } from "react";
import { Destination, Hotel } from "../api/types";
import { api, useApi, useCatalog, EMPTY_DESTINATION } from "../api";
import { useLanguage } from "../context/LanguageContext";
import { ImageWithFallback } from "./ImageWithFallback";
import {
  Building2,
  Star,
  Check,
  ArrowRight,
  SlidersHorizontal,
  Award,
  MapPin,
  CheckCircle2,
  Hotel as HotelIcon,
  Info,
} from "lucide-react";

export type HotelData = Hotel;

type SortCriterion = "value" | "rating" | "price";

interface HotelsViewProps {
  selectedCityId?: string;
  preferredHotels?: Record<string, string>;
  onSelectPreferredHotel?: (cityId: string, hotelId: string) => void;
  onSelectDestination?: (dest: Destination) => void;
  onOpenPlanner?: () => void;
}

export const HotelsView: React.FC<HotelsViewProps> = ({
  selectedCityId,
  preferredHotels,
  onSelectPreferredHotel,
  onSelectDestination,
  onOpenPlanner,
}) => {
  const { language, t, getName } = useLanguage();

  const catalog = useCatalog();
  const activeDestination = catalog.data?.find(d => d.id === selectedCityId) ?? catalog.data?.[0] ?? EMPTY_DESTINATION;
  const cityName = getName(activeDestination);
  const [sortOrder, setSortOrder] = useState<SortCriterion>("value");
  const hotelsRequest = useApi(signal => api.hotels(activeDestination.id, sortOrder, signal), [activeDestination.id, sortOrder], !!activeDestination.id);
  const currentHotels: Hotel[] = hotelsRequest.data ?? [];
  const [localPreferredMap, setLocalPreferredMap] = useState<
    Record<string, string>
  >({});
  const activePreferredMap = preferredHotels || localPreferredMap;
  const currentPreferredHotelId =
    activePreferredMap[activeDestination.id] || currentHotels[0]?.id;

  const [assignedNotice, setAssignedNotice] = useState<string | null>(null);

  const sortedHotels = currentHotels;

  const handleSelectHotel = (hotel: HotelData) => {
    if (onSelectPreferredHotel) {
      onSelectPreferredHotel(activeDestination.id, hotel.id);
    } else {
      setLocalPreferredMap((prev) => ({
        ...prev,
        [activeDestination.id]: hotel.id,
      }));
    }

    setAssignedNotice(
      `Set "${hotel.name}" as preferred stay for ${cityName}. Saved to itinerary engine.`,
    );
    setTimeout(() => {
      setAssignedNotice(null);
    }, 4000);
  };

  const renderStayBadge = (stayType: HotelData["stayType"]) => {
    switch (stayType) {
      case "Toran Hotel":
        return (
          <span className="inline-flex items-center gap-1 bg-ink text-gold border border-gold font-mono text-[10px] font-bold px-2 py-0.5 uppercase tracking-wider rounded-md">
            <Building2 className="w-3 h-3 text-gold" />
            TCGL Official Toran Hotel
          </span>
        );
      case "Heritage Hotel":
        return (
          <span className="inline-flex items-center gap-1 bg-madder text-salt border border-gold font-mono text-[10px] font-bold px-2 py-0.5 uppercase tracking-wider rounded-md">
            <Award className="w-3 h-3 text-gold" />
            Heritage Royal Palace
          </span>
        );
      case "Homestay":
        return (
          <span className="inline-flex items-center gap-1 bg-emerald-900 text-emerald-100 border border-emerald-500 font-mono text-[10px] font-bold px-2 py-0.5 uppercase tracking-wider rounded-md">
            <CheckCircle2 className="w-3 h-3 text-emerald-300" />
            Artisan Village Homestay
          </span>
        );
      case "Registered Hotel":
      default:
        return (
          <span className="inline-flex items-center gap-1 bg-salt text-charcoal border border-stone/50 font-mono text-[10px] font-bold px-2 py-0.5 uppercase tracking-wider rounded-md">
            <HotelIcon className="w-3 h-3 text-ink" />
            Tourism Guild Registered
          </span>
        );
    }
  };

  if(catalog.loading || hotelsRequest.loading) return <p role="status">Loading hotels...</p>;
  if(catalog.error || hotelsRequest.error) return <p role="alert">{catalog.error || hotelsRequest.error} <button onClick={() => {catalog.reload(); hotelsRequest.reload();}}>Retry</button></p>;
  if(!activeDestination.id) return <p role="status">No destinations available.</p>;
  const totalSelectedCount = Object.keys(activePreferredMap).length;

  return (
    <div className="bg-salt min-h-screen py-8 px-4 sm:px-6 lg:px-8 border-b border-stone/30 animate-fadeIn selection:bg-gold selection:text-ink">
      <div className="max-w-5xl mx-auto space-y-8">
        {/* PAGE HEADER */}
        <div className="bg-ink text-salt p-6 sm:p-8 border-2 border-gold space-y-4 shadow-lg relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-stepwell-pattern opacity-10 pointer-events-none" />

          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-stone/30 pb-4">
            <div>
              <div className="flex items-center gap-2 font-mono text-[11px] uppercase tracking-widest text-gold mb-1">
                <Building2 className="w-4 h-4 text-gold" />
                <span>Priority-Queue Stay Audit</span>
              </div>
              <h1 className="font-display text-2xl sm:text-4xl text-salt font-bold">
                {t("nav.hotels", "Hotels")} - {cityName}
              </h1>
            </div>

            <div className="bg-salt/10 border border-stone/40 p-3 font-mono text-xs text-right rounded-lg">
              <span className="text-stone text-[10px] uppercase block tracking-wider">
                Preferred Stays:
              </span>
              <span className="text-gold font-bold text-base">
                {totalSelectedCount} Configured
              </span>
            </div>
          </div>

          <p className="font-mono text-xs text-stone leading-relaxed max-w-2xl">
            Official TCGL Toran Hotels, registered heritage havelis, and artisan
            homestays in {cityName} ranked using our algorithmic value score
            index.
          </p>
        </div>

        {/* NOTICE TOAST */}
        {assignedNotice && (
          <div className="p-3.5 bg-emerald-900 text-salt border-2 border-emerald-400 text-xs font-mono flex items-center justify-between gap-2 shadow-md animate-fadeIn rounded-lg">
            <div className="flex items-center gap-2">
              <Check className="w-4 h-4 text-emerald-300" />
              <span className="font-bold">{assignedNotice}</span>
            </div>
            <span className="text-[10px] text-emerald-300 uppercase font-mono">
              Itinerary Engine Synchronized
            </span>
          </div>
