        {/* ================= CITY CONTEXT BANNER ================= */}
        <div className="bg-white border-2 border-stone/40 p-4 font-mono text-xs text-charcoal flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 shadow-2xs rounded-xl">
