                    {hotel.imageUrl && (
                      <ImageWithFallback
                        src={hotel.imageUrl}
                        alt={`${hotel.name} ${hotel.stayType} exterior`}
                        category="hotel"
                        className="w-16 h-16 sm:w-20 sm:h-20 object-cover border border-stone/30 shrink-0 rounded-lg"
