  onSelectNearbyDestination?: (destId: string) => void;
  onOpenPlannerWithSite?: (dest: Destination) => void;
}

// Note: Full content translation of long narrative descriptions, hotel bios, and attraction details
// is reserved for a follow-up content pass. Core UI labels, headings, buttons, and site/attraction names use active localization.

export const DestinationDetailView: React.FC<DestinationDetailViewProps> = ({
  destination: requestedDestination,
  preferredHotels,
  onSelectPreferredHotel,
  onBack,
  onAddToTrip,
  isAddedToTrip,
  onSelectNearbyDestination,
  onOpenPlannerWithSite,
}) => {
  const { language, t, getName } = useLanguage();
  const request = useApi(signal => api.destination(requestedDestination.id, signal), [requestedDestination.id]);
  const destination = request.data ?? EMPTY_DESTINATION;
  const [wheelchairOnly, setWheelchairOnly] = useState<boolean>(false);
  const [selectedDemands, setSelectedDemands] = useState<
    ("low" | "moderate" | "high")[]
  >([]);

  const toggleDemandFilter = (level: "low" | "moderate" | "high") => {
    setSelectedDemands((prev) =>
      prev.includes(level) ? prev.filter((d) => d !== level) : [...prev, level],
    );
  };

  const filteredAttractions = (destination.attractions || []).filter((attr) => {
    if (wheelchairOnly && !attr.wheelchairAccessible) return false;
    if (
      selectedDemands.length > 0 &&
      !selectedDemands.includes(attr.physicalDemand)
    )
      return false;
    return true;
  });

  if (request.loading) return <p role="status">Loading destination...</p>;
  if (request.error) return <p role="alert">{request.error} <button onClick={request.reload}>Retry</button></p>;
  return (
    <div className="bg-salt min-h-screen border-b border-stone/30 animate-fadeIn">
      {/* 1. FULL-WIDTH HERO IMAGE BAND */}
      <div className="relative h-80 sm:h-96 md:h-[480px] w-full bg-ink overflow-hidden">
        {/* Background Image */}
        <ImageWithFallback
          src={destination.imageUrl}
          alt={destination.imageAlt || getName(destination)}
          category={destination.officialCategory || destination.category}
          className="w-full h-full object-cover hover:scale-105 transition-all duration-700"
        />

        {/* Ink Indigo Gradient Overlay at bottom edge for crisp text contrast */}
        <div className="absolute inset-0 bg-gradient-to-t from-ink via-ink/40 to-transparent" />

        {/* Top Floating Back Breadcrumb */}
        <div className="absolute top-6 left-4 sm:left-6 lg:left-8 z-20">
          <button
            onClick={onBack}
            className="inline-flex items-center gap-2 bg-ink/80 hover:bg-ink text-salt border border-stone/40 hover:border-gold text-xs font-mono px-3.5 py-1.5 backdrop-blur-sm transition-colors cursor-pointer rounded-lg shadow-xs"
          >
            <ArrowLeft className="w-3.5 h-3.5 text-gold" />
            <span>
              {language === "hi"
                ? "सभी स्थलों पर वापस जाएं"
                : "Back to All Destinations"}
            </span>
          </button>
        </div>

        {/* Overlaid Hero Content */}
        <div className="absolute bottom-0 inset-x-0 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-8 z-10 space-y-3">
          <div className="flex flex-wrap items-center gap-2">
            <span className="bg-gold text-ink font-mono text-[11px] font-bold px-3 py-1 uppercase tracking-wider rounded-md">
              {destination.officialCategory}
            </span>
            <span className="bg-ink/80 text-salt font-mono text-[11px] px-3 py-1 border border-stone/40 uppercase rounded-md">
              {destination.district}{" "}
              {language === "hi" ? "ज़िला" : "District"}
            </span>
            <span className="text-gold font-mono text-sm font-bold flex items-center gap-1 bg-ink/80 px-2.5 py-0.5 border border-gold/40 rounded-md">
              <Star className="w-3.5 h-3.5 fill-gold text-gold" />
              {destination.rating}
            </span>
          </div>

          <h1 className="font-display text-3xl sm:text-5xl lg:text-6xl text-salt font-bold tracking-tight leading-tight">
            {getName(destination)}
          </h1>

          <p className="font-mono text-xs text-stone/90 max-w-2xl flex items-center gap-2">
            <Compass className="w-4 h-4 text-gold shrink-0" />
            <span>
              {destination.tag} • {destination.distanceFromAhmedabad}{" "}
              {language === "hi" ? "अहमदाबाद से" : "from Ahmedabad"}
            </span>
          </p>
        </div>
      </div>

      {/* 1.5 SEASONAL ADVISORY BANNER */}
      {destination.seasonalAdvisory &&
        (() => {
          const nowMonth = new Date().getMonth() + 1; // 1..12
          const isActive = destination.seasonalAdvisory.activeMonths.some(
            (m) => {
              const diff = Math.abs(m - nowMonth);
              return diff === 0 || diff === 1 || diff === 11;
            },
          );
          if (!isActive) return null;

          return (
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-6 -mb-4">
              <div className="bg-white border-l-4 border-gold border-y border-r border-stone/30 p-4 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 shadow-sm rounded-xl">
                <div className="flex items-start gap-3">
                  <Calendar className="w-5 h-5 text-gold shrink-0 mt-0.5" />
                  <div className="space-y-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-mono text-xs font-bold text-gold uppercase tracking-wider">
                        {language === "hi"
                          ? "मौसमी यात्रा सलाह"
                          : "Seasonal Travel Advisory"}
                      </span>
                      {destination.seasonalAdvisory.peakWindowLabel && (
                        <span className="bg-gold/10 text-gold border border-gold/30 font-mono text-[10px] px-2 py-0.5 rounded-md font-medium">
                          {destination.seasonalAdvisory.peakWindowLabel}
                        </span>
                      )}
                    </div>
                    <p className="text-xs sm:text-sm text-charcoal/90 font-body leading-relaxed">
                      {destination.seasonalAdvisory.note}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          );
        })()}

      {/* 2. TWO-COLUMN MAIN CONTENT LAYOUT */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 lg:py-14">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 lg:gap-12 items-start">
          {/* LEFT COLUMN (WIDER - lg:col-span-8) */}
          <div className="lg:col-span-8 space-y-10">
            {/* Detailed Description Section */}
            <div className="bg-white p-6 sm:p-8 border border-stone/30 space-y-6 shadow-sm rounded-2xl">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block mb-1">
                  {language === "hi"
                    ? "ऐतिहासिक विवरण और वास्तुकला समीक्षा"
                    : "Heritage Monograph & Architectural Overview"}
                </span>
                <h2 className="font-display text-2xl sm:text-3xl text-charcoal font-bold">
                  {language === "hi"
                    ? `${getName(destination)} के बारे में`
                    : `About ${getName(destination)}`}
                </h2>
              </div>

              <p className="text-stone/90 text-sm sm:text-base leading-relaxed font-body">
                {destination.description}
              </p>

              {/* Highlights List */}
              {destination.highlights && destination.highlights.length > 0 && (
                <div className="pt-4 border-t border-stone/20 space-y-3">
                  <h3 className="font-mono text-xs text-charcoal uppercase tracking-wider font-semibold">
                    {language === "hi"
                      ? "प्रमुख ऐतिहासिक और वास्तुशिल्प विशेषताएं:"
                      : "Key Historical & Architectural Highlights:"}
                  </h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                    {destination.highlights.map((item, idx) => (
                      <div
                        key={idx}
                        className="flex items-center gap-2 text-xs font-mono text-stone bg-salt/60 p-2.5 border border-stone/20 rounded-lg"
                      >
                        <ShieldCheck className="w-4 h-4 text-gold shrink-0" />
                        <span>{item}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Visiting Information Panel */}
            <div className="bg-ink text-salt p-6 sm:p-8 border border-stone/40 space-y-6 rounded-2xl shadow-md">
              <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                {language === "hi"
                  ? "सैलानी अनुभव और समय सारिणी"
                  : "Visitor Experience & Timing Parameters"}
              </span>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 font-mono text-xs">
                <div className="space-y-1 border-l-2 border-gold pl-3">
                  <span className="text-stone uppercase text-[10px]">
                    {language === "hi"
                      ? "उत्तम समय"
                      : "Best Season"}
                  </span>
                  <div className="font-bold text-salt text-sm flex items-center gap-1.5">
                    <Calendar className="w-4 h-4 text-gold shrink-0" />
                    <span>{destination.bestTime}</span>
                  </div>
                  <p className="text-[11px] text-stone/80">
                    {language === "hi"
                      ? "अनुकूल मौसम"
                      : "Optimal climate for heritage walks"}
                  </p>
                </div>

                <div className="space-y-1 border-l-2 border-gold pl-3">
                  <span className="text-stone uppercase text-[10px]">
                    {language === "hi"
                      ? "औसत समय"
                      : "Avg Visit Time"}
                  </span>
                  <div className="font-bold text-salt text-sm flex items-center gap-1.5">
                    <Clock className="w-4 h-4 text-gold shrink-0" />
                    <span>{destination.avgVisitTime}</span>
                  </div>
                  <p className="text-[11px] text-stone/80">
                    {language === "hi"
                      ? "अनुशंसित समय अवधि"
                      : "Recommended exploration duration"}
                  </p>
                </div>

                <div className="space-y-1 border-l-2 border-gold pl-3">
                  <span className="text-stone uppercase text-[10px]">
                    {language === "hi"
                      ? "प्रवेश टिकट"
                      : "Entry Ticket"}
                  </span>
                  <div className="font-bold text-gold text-sm flex items-center gap-1.5">
                    <Ticket className="w-4 h-4 text-gold shrink-0" />
                    <span>{destination.entryFee}</span>
                  </div>
                  <p className="text-[11px] text-stone/80">
                    Official ASI / TCGL tariff
                  </p>
                </div>
              </div>

              {/* Safety & Essential Services Block */}
              {(destination.nearestHospital ||
                destination.nearestPoliceStation) && (
                <div className="pt-4 border-t border-stone/30 font-mono text-xs text-stone space-y-1.5">
                  <span className="text-[11px] uppercase tracking-wider font-semibold text-stone/90 block">
                    Good to know.
                  </span>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-stone/90 text-[11px]">
                    {destination.nearestHospital && (
                      <div className="flex items-center gap-1.5">
                        <Hospital className="w-3.5 h-3.5 text-stone shrink-0" />
                        <span>
                          Nearest hospital: {destination.nearestHospital}
                        </span>
                      </div>
                    )}
                    {destination.nearestPoliceStation && (
                      <div className="flex items-center gap-1.5">
                        <Shield className="w-3.5 h-3.5 text-stone shrink-0" />
                        <span>
                          Nearest police: {destination.nearestPoliceStation}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* INTRA-CITY MONUMENTS & ATTRACTIONS WITH ACCESSIBILITY FILTERS */}
            {destination.attractions && destination.attractions.length > 0 && (
              <div className="bg-white p-6 sm:p-8 border border-stone/30 space-y-6 shadow-sm rounded-2xl">
                <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 border-b border-stone/20 pb-4">
                  <div>
                    <span className="font-mono text-xs text-gold uppercase tracking-widest block mb-1">
                      {language === "hi"
                        ? "शहर के स्मारक और आकर्षण"
                        : "Monuments & Intra-City Heritage Attractions"}
                    </span>
                    <h3 className="font-display text-2xl sm:text-3xl text-charcoal font-bold">
                      {language === "hi"
                        ? `${getName(destination)} मुख्य आकर्षण`
                        : `Key Monuments in ${getName(destination)}`}
                    </h3>
                  </div>
                  <span className="font-mono text-xs text-stone">
                    Showing {filteredAttractions.length} of{" "}
                    {destination.attractions.length} sites
                  </span>
                </div>

                {/* Accessibility Filter Chips Toolbar */}
                <div className="flex flex-wrap items-center gap-2 sm:gap-3 p-3 bg-salt border border-stone/20 font-mono text-xs rounded-xl">
                  <button
                    type="button"
                    onClick={() => setWheelchairOnly(!wheelchairOnly)}
                    className={`inline-flex items-center gap-1.5 px-3 py-1.5 border transition-all cursor-pointer font-semibold rounded-lg ${
                      wheelchairOnly
                        ? "bg-emerald-800 text-salt border-emerald-900 shadow-xs"
                        : "bg-white text-emerald-950 border-emerald-400 hover:bg-emerald-50"
                    }`}
                  >
                    <Accessibility
                      className={`w-4 h-4 ${wheelchairOnly ? "text-emerald-300" : "text-emerald-700"}`}
                    />
                    <span>Wheelchair Accessible</span>
                    {wheelchairOnly && (
                      <span className="text-[10px] bg-emerald-950 text-salt px-1 rounded-sm">
                        ACTIVE
                      </span>
                    )}
                  </button>

                  <span className="text-stone/40 hidden sm:inline">|</span>

                  <div className="flex flex-wrap items-center gap-1.5">
                    <span className="text-stone font-semibold uppercase text-[10px]">
                      Physical Demand:
                    </span>
                    {(["low", "moderate", "high"] as const).map((level) => {
                      const isSelected = selectedDemands.includes(level);
                      const badgeStyle =
                        level === "low"
                          ? isSelected
                            ? "bg-emerald-800 text-salt border-emerald-900"
                            : "bg-white text-emerald-900 border-stone/30 hover:border-emerald-500"
                          : level === "moderate"
                            ? isSelected
                              ? "bg-amber-800 text-salt border-amber-900"
                              : "bg-white text-amber-900 border-stone/30 hover:border-amber-500"
                            : isSelected
                              ? "bg-madder text-salt border-red-900"
                              : "bg-white text-madder border-stone/30 hover:border-red-500";

                      return (
                        <button
                          key={level}
                          type="button"
                          onClick={() => toggleDemandFilter(level)}
                          className={`inline-flex items-center gap-1 px-2.5 py-1 border text-[10px] uppercase transition-all cursor-pointer font-bold rounded-lg ${badgeStyle}`}
                        >
                          <span>{level}</span>
                        </button>
                      );
                    })}
                  </div>

                  {(wheelchairOnly || selectedDemands.length > 0) && (
                    <button
                      type="button"
                      onClick={() => {
                        setWheelchairOnly(false);
                        setSelectedDemands([]);
                      }}
                      className="text-stone hover:text-madder text-[10px] underline ml-auto uppercase font-semibold cursor-pointer"
                    >
                      Reset Filters
                    </button>
                  )}
                </div>

                {/* Attraction Cards Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {filteredAttractions.map((attr) => (
                    <div
                      key={attr.id}
                      className="bg-salt border border-stone/30 p-4 space-y-3 hover:border-gold transition-colors flex flex-col justify-between overflow-hidden rounded-xl"
                    >
                      {attr.imageUrl && (
                        <div className="h-36 sm:h-40 overflow-hidden relative -mx-4 -mt-4 mb-2 border-b border-stone/20 bg-charcoal rounded-t-xl">
                          <ImageWithFallback
                            src={attr.imageUrl}
                            alt={getName(attr)}
                            category={attr.category}
                            className="w-full h-full object-cover hover:scale-105 transition-transform duration-500 rounded-t-xl"
                          />
                        </div>
                      )}
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <span className="font-mono text-[10px] text-gold uppercase font-bold tracking-wider rounded-md">
                            {attr.category}
                          </span>
                          <span className="font-mono text-xs text-gold font-bold flex items-center gap-1 rounded-md">
                            <Star className="w-3.5 h-3.5 fill-gold text-gold" />
                            {attr.rating}
                          </span>
                        </div>

                        <h4 className="font-display text-base font-bold text-charcoal">
                          {getName(attr)}
                        </h4>
                        <BestTimeNote note={attr.bestTimeNote} />

                        <p className="text-xs text-stone line-clamp-2">
                          {attr.description}
                        </p>
                      </div>

                      <div className="space-y-2.5 pt-2 border-t border-stone/20">
                        {/* Accessibility Badges */}
                        <AccessibilityBadge
                          wheelchairAccessible={attr.wheelchairAccessible}
                          physicalDemand={attr.physicalDemand}
                        />

                        <div className="flex items-center justify-between font-mono text-[11px] text-stone">
                          <span>
                            Fee:{" "}
                            <strong className="text-charcoal">
                              {attr.entryFee}
                            </strong>
                          </span>
                          <span>
                            Time:{" "}
                            <strong className="text-charcoal">
                              {attr.durationHours}h
                            </strong>
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* NEARBY ATTRACTIONS TERRACE-MINI-GRID */}
            {destination.nearbyAttractions &&
              destination.nearbyAttractions.length > 0 && (
                <div className="space-y-4">
                  <div className="border-l-2 border-gold pl-3">
                    <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                      {language === "hi"
                        ? "क्षेत्रीय सर्किट"
                        : "Regional Circuit"}
                    </span>
                    <h3 className="font-display text-2xl text-charcoal font-bold">
                      {language === "hi"
                        ? "निकटतम स्मारक और आकर्षण"
                        : "Nearby Monuments & Heritage Attractions"}
                    </h3>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {destination.nearbyAttractions.map((attraction) => (
                      <div
                        key={attraction.id}
                        onClick={() =>
                          onSelectNearbyDestination &&
                          onSelectNearbyDestination(attraction.id)
                        }
                        className="group bg-white p-3.5 border border-stone/30 hover:border-gold transition-all duration-200 cursor-pointer flex gap-3 items-center rounded-xl"
                      >
                        <ImageWithFallback
                          src={attraction.imageUrl}
                          alt={getName(attraction)}
                          category={attraction.category}
                          className="w-20 h-20 object-cover group-hover:scale-105 transition-all shrink-0 border border-stone/20 rounded-lg"
                        />
                        <div className="space-y-1 flex-1 min-w-0">
                          <span className="text-[10px] font-mono text-gold uppercase block truncate">
                            {attraction.category}
                          </span>
                          <h4 className="font-display text-base font-bold text-charcoal group-hover:text-gold transition-colors truncate">
                            {getName(attraction)}
                          </h4>
                          <span className="text-xs font-mono text-stone flex items-center gap-1">
                            <MapPin className="w-3 h-3 text-gold" />
                            {attraction.distance}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
          </div>

          {/* RIGHT COLUMN (NARROWER - lg:col-span-4, STICKY ON DESKTOP) */}
          <div className="lg:col-span-4 lg:sticky lg:top-24 space-y-6">
            <div className="bg-ink text-salt p-6 border-2 border-gold/60 space-y-6 shadow-md rounded-2xl">
              <div className="border-b border-stone/30 pb-4">
                <span className="font-mono text-xs text-gold uppercase tracking-wider block mb-1">
                  {language === "hi"
                    ? "आधिकारिक सारांश"
                    : "Official Heritage Summary"}
                </span>
                <h3 className="font-display text-2xl font-bold text-salt">
                  {getName(destination)}
                </h3>
              </div>

              {/* IBM Plex Mono Logistical Specs Panel */}
              <div className="space-y-3 font-mono text-xs">
                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "प्रवेश शुल्क"
                      : "Entry Fee"}
                  </span>
                  <span className="text-gold font-bold">
                    {destination.entryFee}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "औसत समय"
                      : "Avg Visit Time"}
                  </span>
                  <span className="text-salt font-semibold">
                    {destination.avgVisitTime}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "ज़िला"
                      : "District"}
                  </span>
                  <span className="text-salt font-semibold">
                    {destination.district}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "श्रेणी"
                      : "Category"}
                  </span>
                  <span className="text-salt font-semibold text-[11px] truncate max-w-[150px]">
                    {destination.officialCategory}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2 border-b border-stone/30">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "अहमदाबाद से"
                      : "From Ahmedabad"}
                  </span>
                  <span className="text-salt font-semibold">
                    {destination.distanceFromAhmedabad}
                  </span>
                </div>

                <div className="flex items-center justify-between py-2">
                  <span className="text-stone uppercase">
                    {language === "hi"
                      ? "रेटिंग"
                      : "Visitor Rating"}
                  </span>
                  <span className="text-gold font-bold">
                    {destination.rating}
                  </span>
                </div>
              </div>

              {/* MADDER RED ACTION BUTTON: "Add to Trip Plan" */}
              <div className="space-y-2 pt-2">
                <button
                  onClick={() => onAddToTrip(destination)}
                  className={`w-full py-3.5 px-4 text-xs font-mono uppercase tracking-wider font-bold transition-all duration-200 flex items-center justify-center gap-2 border cursor-pointer rounded-lg shadow-xs ${
                    isAddedToTrip
                      ? "bg-emerald-800 text-salt border-emerald-600"
                      : "bg-madder hover:bg-madder/90 text-salt border-madder"
                  }`}
                >
                  {isAddedToTrip ? (
                    <>
                      <CheckCircle2 className="w-4 h-4 text-emerald-300" />
                      <span>
                        {language === "hi"
                          ? "योजना में जोड़ा गया"
                          : "Added to Trip Plan"}
                      </span>
                    </>
                  ) : (
                    <>
                      <PlusCircle className="w-4 h-4 text-salt" />
                      <span>{t("explore.plan", "Add to Trip Plan")}</span>
                    </>
                  )}
                </button>

                {onOpenPlannerWithSite && (
                  <button
                    onClick={() => onOpenPlannerWithSite(destination)}
                    className="w-full py-2.5 px-4 bg-transparent hover:bg-salt/10 text-gold hover:text-salt border border-gold/40 text-xs font-mono uppercase tracking-wider font-semibold transition-colors flex items-center justify-center gap-1.5 cursor-pointer rounded-lg"
                  >
                    <span>
                      {language === "hi"
                        ? "कस्टम यात्रा प्लान करें"
                        : "Build Custom Itinerary"}
                    </span>
                    <ChevronRight className="w-3.5 h-3.5" />
                  </button>
                )}
              </div>

              <p className="text-[10px] font-mono text-stone text-center">
                {language === "hi"
                  ? "साइट को सीधे आपके सक्रिय रूट प्लानर में जोड़ता है।"
                  : "Adds site directly to your active route builder in the navigation bar."}
              </p>
            </div>
          </div>
        </div>

        {/* 3. SUGGESTED HOTELS NEAR HERE STRIP */}
        {destination.nearbyHotels && destination.nearbyHotels.length > 0 && (
          <div className="mt-16 pt-10 border-t border-stone/30 space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-2 border-l-2 border-gold pl-3">
              <div>
                <span className="font-mono text-xs text-gold uppercase tracking-widest block">
                  {language === "hi"
                    ? "हेरिटेज स्टे निवास"
                    : "Heritage Stay Accommodations"}
                </span>
                <h3 className="font-display text-2xl text-charcoal font-bold">
                  {language === "hi"
                    ? `${getName(destination)} के निकटतम होटल`
                    : `Suggested Hotels Near ${getName(destination)}`}
                </h3>
              </div>
              <span className="font-mono text-xs text-stone">
                Toran TCGL Bungalows & Restored Haveli Stays
              </span>
            </div>

            {/* Horizontally Scrollable Row of Hotel Cards */}
            <div className="flex items-stretch gap-6 overflow-x-auto pb-4 scrollbar-none">
              {destination.nearbyHotels.map((hotel) => (
                <div
                  key={hotel.id}
                  className="bg-ink text-salt border border-stone/40 min-w-[280px] sm:min-w-[320px] max-w-[340px] flex-shrink-0 flex flex-col justify-between p-4 space-y-4 rounded-2xl shadow-md"
                >
                  <div className="relative h-40 overflow-hidden border border-stone/30 bg-charcoal rounded-xl">
                    <ImageWithFallback
                      src={hotel.imageUrl}
                      alt={hotel.name}
                      category="hotel"
                      className="w-full h-full object-cover hover:scale-105 transition-all duration-300 rounded-xl"
                    />

                    {/* Official Stay Type Badge */}
                    <span className="absolute top-2 left-2 bg-salt text-ink font-mono text-[10px] font-bold px-2 py-0.5 uppercase tracking-wider rounded-md">
                      {hotel.stayType}
                    </span>

                    {/* Rating Badge */}
                    <span className="absolute bottom-2 right-2 bg-ink/90 text-gold font-mono text-[10px] font-bold px-2 py-0.5 border border-gold/40 rounded-md">
                      {hotel.rating}
                    </span>
                  </div>

                  <div className="space-y-1">
                    <h4 className="font-display text-lg font-bold text-salt leading-tight">
                      {hotel.name}
                    </h4>
                    <p className="text-xs font-mono text-stone flex items-center gap-1">
                      <Hotel className="w-3.5 h-3.5 text-gold shrink-0" />
                      <span>{hotel.location}</span>
                    </p>
                  </div>

                  <div className="flex items-center justify-between pt-3 border-t border-stone/30 text-xs font-mono">
                    <span className="text-stone">
                      {language === "hi"
                        ? "किराया:"
                        : "Tariff:"}
                    </span>
                    <span className="text-gold font-bold">
                      {hotel.pricePerNight}
                    </span>
                  </div>

                  {onSelectPreferredHotel && (
                    <button
                      onClick={() =>
                        onSelectPreferredHotel(destination.id, hotel.id)
                      }
                      className={`w-full py-2 px-3 text-xs font-mono font-bold uppercase transition-all cursor-pointer flex items-center justify-center gap-1.5 border rounded-lg ${
                        preferredHotels?.[destination.id] === hotel.id
                          ? "bg-gold text-ink border-gold shadow-xs"
                          : "bg-salt/10 hover:bg-gold hover:text-ink text-salt border-stone/40"
                      }`}
                    >
                      {preferredHotels?.[destination.id] === hotel.id ? (
                        <>
                          <CheckCircle2 className="w-3.5 h-3.5 text-ink shrink-0" />
                          <span>
                            {language === "hi"
                              ? "चयनित स्थान"
                              : "Preferred Stay Selected"}
                          </span>
                        </>
                      ) : (
                        <span>
                          {language === "hi"
                            ? "पसंदीदा स्थान चुनें"
                            : "Set as Preferred Stay"}
                        </span>
                      )}
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

frontend/src/components/StrategyComparis:
import { displayNumber } from "../api";
import { createItinerary, useApi, generateComparisonTakeaway } from "../api";
import React, { useState, useMemo } from "react";
import type {
  PlannerConfigPayload,
  OptimizationStrategy,
  GeneratedItineraryResult,
} from "../utils/itineraryPlanner";
import { useLanguage } from "../context/LanguageContext";
import { AlgorithmStatsPanel } from "./AlgorithmStatsPanel";
import {
  X,
  SlidersHorizontal,
  Compass,
  Check,
  Building,
  MapPin,
  Clock,
  DollarSign,
  Star,
  Zap,
  TrendingDown,
  Navigation,
  Sparkles,
  ChevronDown,
  ChevronUp,
} from "lucide-react";

interface StrategyComparisonModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: PlannerConfigPayload;
  onSelectStrategy: (strategy: OptimizationStrategy, config?: PlannerConfigPayload) => void;
}

export const StrategyComparisonModal: React.FC<
  StrategyComparisonModalProps
> = ({ isOpen, onClose, config, onSelectStrategy }) => {
  const { language, t, getName } = useLanguage();
  const [activeMobileTab, setActiveMobileTab] =
    useState<OptimizationStrategy>("budget-first");
  const [expandedDayPlans, setExpandedDayPlans] = useState<Record<string, boolean>>({});

  const request = useApi(async signal => {
    const rows = [];
    for(const strategy of ["budget-first", "rating-first", "distance-first"] as OptimizationStrategy[]) {
      signal.throwIfAborted();
      rows.push(await createItinerary(config, strategy));
    }
    return rows;
  }, [config.cityId,config.tripDays,config.budget,config.startingHotelId,config.startTime,config.wheelchairAccessibleOnly,isOpen], isOpen);
  const results = request.data?.map(row => row.result) ?? [];
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { if(e.key === "Escape") onClose(); };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);
  if(!isOpen) return null;
  if(request.loading) return <p role="status">Loading server-generated comparisons... <button onClick={onClose}>Close</button></p>;
  if(request.error) return <p role="alert">{request.error} <button onClick={request.reload}>Retry</button> <button onClick={onClose}>Close</button></p>;
  if(results.length < 3) return <p role="status">Comparison unavailable.</p>;

  const budgetResult = results[0];
  const ratingResult = results[1];
  const distanceResult = results[2];

  // Compute winning values for each metric row/column in comparison table
  const winningDistance = Math.min(...results.map((r) => r.totalDistanceKm));
  const winningCost = Math.min(...results.map((r) => r.totalCost));
  const winningAttractions = Math.max(...results.map((r) => r.attractionCount));
  const winningRuntime = Math.min(...results.map((r) => r.totalRuntimeMinutes));

  // Dynamic One-line Takeaway
  const takeawayText = generateComparisonTakeaway(results);

  const strategyMeta: Record<
    OptimizationStrategy,
    {
      title: string;
      subtitle: string;
      icon: React.ReactNode;
      badgeColor: string;
      description: string;
    }
  > = {
    "budget-first": {
      title: "Budget-first",
      subtitle: "Greedy cost & fee minimization",
      icon: <TrendingDown className="w-4 h-4 text-emerald-400" />,
      badgeColor: "border-emerald-600/50 bg-emerald-950/20 text-emerald-300",
      description: "Strictly minimizes hotel tariff, entrance fees, and meal expenses.",
    },
    "rating-first": {
      title: "Rating-first",
      subtitle: "Top-rated heritage quality",
      icon: <Star className="w-4 h-4 text-gold" />,
      badgeColor: "border-gold/50 bg-amber-950/20 text-gold",
      description: "Prioritizes highest-rated monuments (>= 4.6★) and heritage stays.",
    },
    "distance-first": {
      title: "Distance-first",
      subtitle: "Nearest-neighbor distance minimization",
      icon: <Navigation className="w-4 h-4 text-sky-400" />,
      badgeColor: "border-sky-600/50 bg-sky-950/20 text-sky-300",
      description: "Groups geographically proximate stops to reduce drive time.",
    },
  };

  const toggleDayPlan = (strategyKey: string) => {
    setExpandedDayPlans((prev) => ({
      ...prev,
      [strategyKey]: !prev[strategyKey],
    }));
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="strategy-comparison-title"
      className="fixed inset-0 z-50 flex items-center justify-center p-2 sm:p-4 bg-ink/90 backdrop-blur-sm overflow-y-auto"
      onClick={onClose}
    >
      <div
        className="bg-salt border-2 border-gold max-w-6xl w-full text-charcoal p-3 sm:p-6 md:p-8 relative shadow-2xl my-2 sm:my-8 animate-fadeIn max-h-[94vh] flex flex-col rounded-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Modal Header */}
        <div className="flex items-start justify-between border-b border-stone/30 pb-3 mb-4 shrink-0">
          <div>
            <div className="flex items-center gap-2 font-mono text-xs text-gold uppercase tracking-widest mb-1">
              <SlidersHorizontal className="w-4 h-4 text-gold shrink-0" />
              <span>Stepwell Optimization Comparison</span>
            </div>
            <h2 id="strategy-comparison-title" className="font-display text-xl sm:text-3xl text-ink font-bold leading-tight">
              Compare Optimization Strategies — {getName(budgetResult.activeCity)}
            </h2>
            <p className="font-body text-xs text-stone mt-0.5">
              Evaluating 3 greedy route algorithms for your {config.tripDays}
              -day trip with a budget cap of ₹{displayNumber(config.budget)}.
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-stone hover:text-ink hover:bg-stone/20 border border-stone/30 transition-colors cursor-pointer shrink-0 ml-2 rounded-lg"
            aria-label="Close strategy comparison"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Scrollable Container for Modal Body */}
        <div className="overflow-y-auto space-y-4 sm:space-y-6 pr-1">
          {/* ================= 1. DYNAMIC ONE-LINE TAKEAWAY BANNER ================= */}
          <div className="bg-ink text-salt border-2 border-gold p-3 sm:p-4 relative shadow-md bg-stepwell-pattern rounded-xl">
            <div className="flex items-start gap-3">
              <div className="p-1.5 sm:p-2 bg-gold/20 border border-gold text-gold rounded-lg shrink-0 mt-0.5">
                <Sparkles className="w-4 h-4 sm:w-5 sm:h-5 text-gold animate-pulse" />
              </div>
              <div>
                <span className="font-mono text-[10px] text-gold uppercase tracking-widest font-bold block mb-0.5">
                  Algorithmic Trade-off Takeaway
                </span>
                <p className="font-display text-sm sm:text-lg text-salt font-medium leading-snug">
                  "{takeawayText}"
                </p>
              </div>
            </div>
          </div>

          {/* ================= 2. DESKTOP METRIC COMPARISON TABLE ================= */}
          <div className="hidden md:block bg-white border border-stone/30 p-4 shadow-sm rounded-xl">
            <h3 className="font-mono text-xs font-bold uppercase tracking-wider text-charcoal mb-3 flex items-center justify-between">
              <span>Strategy Metrics Overview</span>
              <span className="text-[10px] font-normal text-stone font-mono">
                <span className="text-gold font-bold">★ Gold</span> = Winning stat per metric
              </span>
            </h3>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse font-mono text-xs">
                <thead>
                  <tr className="bg-salt border-b-2 border-stone/30 text-stone uppercase tracking-wider">
                    <th className="p-2.5 font-bold text-ink">Strategy Name</th>
                    <th className="p-2.5 font-bold text-ink">Total Cost (₹)</th>
                    <th className="p-2.5 font-bold text-ink">Distance (km)</th>
                    <th className="p-2.5 font-bold text-ink">Attractions</th>
                    <th className="p-2.5 font-bold text-ink">Est. Runtime</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-stone/20">
                  {results.map((res) => {
                    const meta = strategyMeta[res.strategy];
                    const isWinningDist = res.totalDistanceKm === winningDistance;
                    const isWinningCost = res.totalCost === winningCost;
                    const isWinningAttr = res.attractionCount === winningAttractions;
                    const isWinningRuntime = res.totalRuntimeMinutes === winningRuntime;

                    return (
                      <tr
                        key={res.strategy}
                        className="hover:bg-salt/60 transition-colors"
                      >
                        <td className="p-2.5 font-bold text-ink flex items-center gap-2">
                          {meta.icon}
                          <span className="font-body text-sm font-semibold">
                            {meta.title}
                          </span>
                          <span
                            className={`text-[10px] px-1.5 py-0.5 border font-mono ${meta.badgeColor}`}
                          >
                            {res.strategy}
                          </span>
                        </td>

                        {/* Cost Cell */}
                        <td className="p-2.5">
                          <span
                            className={`font-mono text-xs px-2 py-1 ${
                              isWinningCost
                                ? "bg-amber-100 text-amber-900 font-bold border border-gold shadow-xs"
                                : "text-charcoal"
                            }`}
                          >
                            {isWinningCost && (
                              <span className="text-gold mr-1">★</span>
                            )}
                            ₹{displayNumber(res.totalCost)}
                          </span>
                        </td>

                        {/* Distance Cell */}
                        <td className="p-2.5">
                          <span
                            className={`font-mono text-xs px-2 py-1 ${
                              isWinningDist
                                ? "bg-amber-100 text-amber-900 font-bold border border-gold shadow-xs"
                                : "text-charcoal"
                            }`}
                          >
                            {isWinningDist && (
                              <span className="text-gold mr-1">★</span>
                            )}
                            {res.totalDistanceKm} km
                          </span>
                        </td>

                        {/* Attractions Cell */}
                        <td className="p-2.5">
                          <span
                            className={`font-mono text-xs px-2 py-1 rounded-md ${
                              isWinningAttr
                                ? "bg-amber-100 text-amber-900 font-bold border border-gold shadow-xs"
                                : "text-charcoal"
                            }`}
                          >
                            {isWinningAttr && (
                              <span className="text-gold mr-1">★</span>
                            )}
                            {res.attractionCount} sites
                          </span>
                        </td>

                        {/* Est. Runtime Cell */}
                        <td className="p-2.5">
                          <span
                            className={`font-mono text-xs px-2 py-1 rounded-md ${
                              isWinningRuntime
                                ? "bg-amber-100 text-amber-900 font-bold border border-gold shadow-xs"
                                : "text-charcoal"
                            }`}
                          >
                            {isWinningRuntime && (
                              <span className="text-gold mr-1">★</span>
                            )}
                            {res.totalRuntimeHours}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>

          {/* ================= 3. MOBILE TAB SWITCHER ================= */}
          <div className="md:hidden flex border-2 border-stone/30 bg-salt p-1 gap-1 rounded-xl">
            {results.map((res) => {
              const isActive = activeMobileTab === res.strategy;
              const meta = strategyMeta[res.strategy];
              return (
                <button
                  key={res.strategy}
                  type="button"
                  onClick={() => setActiveMobileTab(res.strategy)}
                  className={`flex-1 py-2 px-1 text-xs font-mono font-bold flex items-center justify-center gap-1 cursor-pointer transition-all min-h-[44px] rounded-lg ${
                    isActive
                      ? "bg-ink text-gold border border-gold shadow-sm"
                      : "text-stone hover:text-charcoal bg-white border border-stone/20"
                  }`}
                >
                  {meta.icon}
                  <span className="text-[11px] truncate">{meta.title}</span>
                </button>
              );
            })}
          </div>

          {/* ================= 4. THREE TERRACE-OFFSET STRATEGY COLUMNS ================= */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6 items-start pb-2">
            {results.map((res, idx) => {
              const meta = strategyMeta[res.strategy];
              const terraceClass =
                idx === 0 ? "mt-0" : idx === 1 ? "md:mt-3" : "md:mt-6";
              const isMobileHidden = activeMobileTab !== res.strategy;
              const isDaysExpanded = expandedDayPlans[res.strategy] ?? true;

              return (
                <div
                  key={res.strategy}
                  className={`bg-white border-2 border-stone/30 shadow-md flex flex-col transition-all rounded-2xl overflow-hidden ${terraceClass} ${
                    isMobileHidden ? "hidden md:flex" : "flex"
                  }`}
                >
                  {/* Column Terrace Header */}
                  <div className="bg-ink text-salt p-3 sm:p-4 border-b-2 border-gold relative">
                    <div className="flex items-center justify-between mb-1">
                      <span className="font-mono text-[10px] uppercase text-gold font-bold flex items-center gap-1">
                        {meta.icon}
                        Option 0{idx + 1}
                      </span>
                      <span className="font-mono text-[10px] text-stone text-right">
                        Terrace Step {idx + 1}
                      </span>
                    </div>
                    <h4 className="font-display text-lg sm:text-xl font-bold text-salt">
                      {meta.title}
                    </h4>
                    <p className="font-body text-xs text-stone/90 mt-0.5">
                      {meta.description}
                    </p>
                  </div>

                  {/* Column Key Metrics Cards */}
                  <div className="p-3 bg-salt border-b border-stone/20 grid grid-cols-2 gap-2 font-mono text-xs">
                    <div className="bg-white p-2 border border-stone/30 rounded-lg">
                      <span className="text-[10px] text-stone uppercase block">
                        Total Cost
                      </span>
                      <span className="font-bold text-ink text-sm">
                        ₹{displayNumber(res.totalCost)}
                      </span>
                    </div>
                    <div className="bg-white p-2 border border-stone/30 rounded-lg">
                      <span className="text-[10px] text-stone uppercase block">
                        Distance
                      </span>
                      <span className="font-bold text-ink text-sm">
                        {res.totalDistanceKm} km
                      </span>
                    </div>
                    <div className="bg-white p-2 border border-stone/30 rounded-lg">
                      <span className="text-[10px] text-stone uppercase block">
                        Attractions
                      </span>
                      <span className="font-bold text-ink text-sm">
                        {res.attractionCount} sites
                      </span>
                    </div>
                    <div className="bg-white p-2 border border-stone/30 rounded-lg">
                      <span className="text-[10px] text-stone uppercase block">
                        Est. Runtime
                      </span>
                      <span className="font-bold text-ink text-sm">
                        {res.totalRuntimeHours}
                      </span>
                    </div>
                  </div>

                  {/* Column Execution Algorithm Stats Strip */}
                  {res.stats && (
                    <div className="p-2 bg-ink border-b border-stone/30">
                      <AlgorithmStatsPanel
                        stats={res.stats}
                        collapsible={true}
                        defaultExpanded={false}
                        title="Execution Stats"
                      />
                    </div>
                  )}

                  {/* Column Condensed Day-by-Day Schedule */}
                  <div className="p-3 flex-grow space-y-3">
                    <div className="flex items-center justify-between border-b border-stone/30 pb-1">
                      <span className="font-mono text-xs font-bold text-charcoal uppercase">
                        Route Schedule ({res.dayPlans.length} Days)
                      </span>
                      <button
                        type="button"
                        onClick={() => toggleDayPlan(res.strategy)}
                        className="text-[11px] font-mono text-gold hover:text-ink flex items-center gap-1 cursor-pointer"
                      >
                        <span>{isDaysExpanded ? "Collapse" : "Expand"}</span>
                        {isDaysExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                      </button>
                    </div>

                    {isDaysExpanded && (
                      <div className="space-y-3 max-h-[280px] sm:max-h-[340px] overflow-y-auto pr-1">
                        {res.dayPlans.map((day) => (
                          <div key={day.dayNumber} className="space-y-1.5">
                            <div className="flex items-center justify-between border-b border-stone/20 pb-0.5">
                              <span className="font-mono text-xs font-bold text-gold uppercase">
                                {day.dateLabel}
                              </span>
                              <span className="font-mono text-[10px] text-stone">
                                {day.totalKm} km • ₹{day.totalCost}
                              </span>
                            </div>

                            <div className="space-y-1.5 pl-1.5 border-l-2 border-gold/40">
                              {day.stops.map((stop) => (
                                <div
                                  key={stop.id}
                                  className="bg-salt/80 p-1.5 border border-stone/20 text-xs space-y-0.5 hover:bg-salt transition-colors rounded-lg"
                                >
                                  <div className="flex items-center justify-between text-[10px] font-mono">
                                    <span className="bg-ink/10 text-ink px-1 py-0.2 font-bold rounded-sm">
                                      {stop.arrivalTime}
                                    </span>
                                    <span className="text-stone truncate max-w-[120px]">
                                      {stop.category}
                                    </span>
                                  </div>
                                  <div className="font-body font-medium text-charcoal text-xs leading-tight line-clamp-1">
                                    {stop.name}
                                  </div>
                                  {stop.cost > 0 && (
                                    <div className="font-mono text-[10px] text-stone text-right">
                                      Cost: ₹{stop.cost}
                                    </div>
                                  )}
                                </div>
                              ))}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Column Bottom Action: Madder Red "Use this plan" Button */}
                  <div className="p-3 sm:p-4 bg-salt border-t border-stone/20 shrink-0">
                    <button
                      type="button"
                      onClick={() => onSelectStrategy(res.strategy, request.data?.find(row => row.result.strategy === res.strategy)?.config)}
                      className="w-full bg-madder hover:bg-ink text-salt border border-madder font-mono text-xs font-bold py-3 px-4 uppercase tracking-wider flex items-center justify-center gap-2 cursor-pointer shadow-md hover:shadow-xl transition-all min-h-[44px] rounded-lg"
                    >
                      <Check className="w-4 h-4 text-salt" />
                      <span>Use this plan</span>
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

frontend/src/components/DijkstraVisualiz:
import React, { useState, useEffect, useRef } from "react";
import {
  Play,
  Pause,
  SkipForward,
  RotateCcw,
  Cpu,
  CheckCircle,
  Info,
} from "lucide-react";
import { SVG_COLORS } from "../data/colors";
import { api, useApi } from "../api";

export interface GraphNode {
  id: string;
  name: string;
  shortName: string;
  x: number;
  y: number;
}

export interface GraphEdge {
  from: string;
  to: string;
  distanceKm: number;
}

// Graph presentation from persisted journey legs; no synthetic catalog nodes.
export function getIntraCityGraph(dto: any): { nodes: GraphNode[]; edges: GraphEdge[] } {
  const stops = dto?.days?.flatMap((day: any) => day.stops) ?? [];
  const unique = [...new Map<string, any>(stops.map((stop: any) => [stop.reference_id, stop])).values()];
  const nodes = unique.map((stop, index) => ({id:stop.reference_id,name:stop.name,shortName:stop.name.split(" ")[0],
    x:100 + (index % 4) * 110,y:90 + Math.floor(index / 4) * 90}));
  const edges = (dto?.trip?.generation_summary?.legs ?? []).map((leg: any) => ({from:leg.from,to:leg.to,distanceKm:Number(leg.distance_km)}));
  return {nodes,edges};
}

export interface AlgorithmStep {
  stepIndex: number;
  description: string;
  currentNodeId: string | null;
  visitedNodeIds: string[];
  frontierNodeIds: string[];
  distances: Record<string, number>;
  previous: Record<string, string | null>;
  activeEdge: { from: string; to: string } | null;
  relaxedEdge: { from: string; to: string } | null;
  isComplete: boolean;
  finalPath: string[];
  finalDistance: number;
}

// Dijkstra Algorithm step generator
export function generateDijkstraSteps(
  startId: string = "hotel",
  targetId: string = "resto",
  nodesList: GraphNode[] = [],
  edgesList: GraphEdge[] = [],
): AlgorithmStep[] {
  const steps: AlgorithmStep[] = [];

  const distances: Record<string, number> = {};
  const previous: Record<string, string | null> = {};
  const unvisited = new Set<string>();

  nodesList.forEach((node) => {
    distances[node.id] = Infinity;
    previous[node.id] = null;
    unvisited.add(node.id);
  });

  const effectiveStart = nodesList.some((n) => n.id === startId)
    ? startId
    : nodesList[0]?.id || "hotel";
  const effectiveTarget = nodesList.some((n) => n.id === targetId)
    ? targetId
    : nodesList[nodesList.length - 1]?.id || "resto";

  distances[effectiveStart] = 0;

  const getNeighbors = (nodeId: string) => {
    const neighbors: { neighborId: string; weight: number }[] = [];
    edgesList.forEach((edge) => {
      if (edge.from === nodeId)
        neighbors.push({ neighborId: edge.to, weight: edge.distanceKm });
      else if (edge.to === nodeId)
        neighbors.push({ neighborId: edge.from, weight: edge.distanceKm });
    });
    return neighbors;
  };

  const visitedNodes: string[] = [];
  let frontierNodes: string[] = [effectiveStart];

  // Initial step
  steps.push({
    stepIndex: 0,
    description: `Initialize Dijkstra search from start node (${nodesList.find((n) => n.id === effectiveStart)?.shortName || effectiveStart}). Distance = 0 km.`,
    currentNodeId: effectiveStart,
    visitedNodeIds: [],
    frontierNodeIds: [effectiveStart],
    distances: { ...distances },
    previous: { ...previous },
    activeEdge: null,
    relaxedEdge: null,
    isComplete: false,
    finalPath: [],
    finalDistance: 0,
  });

  while (unvisited.size > 0) {
    // Select unvisited node with smallest distance
    let currentId: string | null = null;
    let minDistance = Infinity;

    unvisited.forEach((nodeId) => {
      if (distances[nodeId] < minDistance) {
        minDistance = distances[nodeId];
        currentId = nodeId;
      }
    });

    if (currentId === null || minDistance === Infinity) {
      break; // Remaining nodes unreachable
    }

    unvisited.delete(currentId);
    if (!visitedNodes.includes(currentId)) {
      visitedNodes.push(currentId);
    }
    frontierNodes = frontierNodes.filter((id) => id !== currentId);

    const currentNodeObj = nodesList.find((n) => n.id === currentId);

    steps.push({
      stepIndex: steps.length,
      description: `Evaluate node [${currentNodeObj?.shortName || currentId}] (shortest distance so far = ${distances[currentId]} km).`,
      currentNodeId: currentId,
      visitedNodeIds: [...visitedNodes],
      frontierNodeIds: [...frontierNodes],
      distances: { ...distances },
      previous: { ...previous },
      activeEdge: null,
      relaxedEdge: null,
      isComplete: false,
      finalPath: [],
      finalDistance: 0,
    });

    // Check if target reached
    if (currentId === effectiveTarget) {
      break;
    }

    // Examine neighbors
    const neighbors = getNeighbors(currentId);
    for (const { neighborId, weight } of neighbors) {
      if (unvisited.has(neighborId)) {
        if (!frontierNodes.includes(neighborId)) {
          frontierNodes.push(neighborId);
        }

        const alt = distances[currentId] + weight;
        const neighborObj = nodesList.find((n) => n.id === neighborId);

        steps.push({
          stepIndex: steps.length,
          description: `Examine edge (${currentNodeObj?.shortName} → ${neighborObj?.shortName}): distance ${distances[currentId]} + ${weight} = ${alt} km.`,
          currentNodeId: currentId,
          visitedNodeIds: [...visitedNodes],
          frontierNodeIds: [...frontierNodes],
          distances: { ...distances },
          previous: { ...previous },
          activeEdge: { from: currentId, to: neighborId },
          relaxedEdge: null,
          isComplete: false,
          finalPath: [],
          finalDistance: 0,
        });

        if (alt < distances[neighborId]) {
          distances[neighborId] = alt;
          previous[neighborId] = currentId;

          steps.push({
            stepIndex: steps.length,
            description: `Relax edge! New shortest path to [${neighborObj?.shortName}] updated to ${alt} km.`,
            currentNodeId: currentId,
            visitedNodeIds: [...visitedNodes],
            frontierNodeIds: [...frontierNodes],
            distances: { ...distances },
            previous: { ...previous },
            activeEdge: { from: currentId, to: neighborId },
            relaxedEdge: { from: currentId, to: neighborId },
            isComplete: false,
            finalPath: [],
            finalDistance: 0,
          });
        }
      }
    }
  }

  // Construct final path
  const finalPath: string[] = [];
  let curr: string | null = effectiveTarget;
  if (distances[effectiveTarget] !== Infinity) {
    while (curr) {
      finalPath.unshift(curr);
      curr = previous[curr];
    }
  }

  const finalDist =
    distances[effectiveTarget] !== Infinity ? distances[effectiveTarget] : 0;

  steps.push({
    stepIndex: steps.length,
    description: `Dijkstra search complete! Shortest path identified (${finalDist} km).`,
    currentNodeId: null,
    visitedNodeIds: [...visitedNodes],
    frontierNodeIds: [],
    distances: { ...distances },
    previous: { ...previous },
    activeEdge: null,
    relaxedEdge: null,
    isComplete: true,
    finalPath,
    finalDistance: Math.round(finalDist * 10) / 10,
  });

  return steps;
}

interface DijkstraVisualizerProps {
  tripId?: string;
  cityId?: string;
  startNodeId?: string;
  targetNodeId?: string;
}

export const DijkstraVisualizer: React.FC<DijkstraVisualizerProps> = ({
  cityId,
  tripId,
  startNodeId,
  targetNodeId,
}) => {
  const request = useApi(signal => api.trip(tripId ?? "", signal), [tripId]);
  const intraGraph = getIntraCityGraph(request.data);
  const activeNodes = intraGraph.nodes;
  const activeEdges = intraGraph.edges;

  const [startId, setStartId] = useState<string>(
    startNodeId || activeNodes[0]?.id || "hotel",
  );
  const [targetId, setTargetId] = useState<string>(
    targetNodeId || activeNodes[activeNodes.length - 1]?.id || "resto",
  );

  const [steps, setSteps] = useState<AlgorithmStep[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState<number>(0);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [hasReducedMotion, setHasReducedMotion] = useState<boolean>(false);

  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Check prefers-reduced-motion
  useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    setHasReducedMotion(mediaQuery.matches);

    const handleChange = (e: MediaQueryListEvent) => {
      setHasReducedMotion(e.matches);
    };

    mediaQuery.addEventListener?.("change", handleChange);
    return () => mediaQuery.removeEventListener?.("change", handleChange);
  }, []);

  useEffect(() => {
    setStartId(startNodeId || activeNodes[0]?.id || "");
    setTargetId(targetNodeId || activeNodes.at(-1)?.id || "");
  }, [request.data]);
  // Regenerate steps when start, target or city changes
  useEffect(() => {
    if(!activeNodes.length || !activeEdges.length) { setSteps([]); return; }
    const generated = generateDijkstraSteps(
      startId,
      targetId,
      activeNodes,
      activeEdges,
    );
    setSteps(generated);

    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    if (mediaQuery.matches) {
      // If reduced motion, jump straight to final step
      setCurrentStepIndex(generated.length - 1);
      setIsPlaying(false);
    } else {
      setCurrentStepIndex(0);
      setIsPlaying(false);
    }
  }, [startId, targetId, cityId, request.data]);

  // Handle Playback Timer
  useEffect(() => {
    if (isPlaying && steps.length > 0) {
      timerRef.current = setInterval(() => {
        setCurrentStepIndex((prevIndex) => {
          if (prevIndex >= steps.length - 1) {
            setIsPlaying(false);
            if (timerRef.current) clearInterval(timerRef.current);
            return prevIndex;
          }
          return prevIndex + 1;
        });
      }, 700);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isPlaying, steps]);

  const currentStep = steps[currentStepIndex] || steps[0];

  const handlePlayPause = () => {
    if (currentStepIndex >= steps.length - 1) {
      setCurrentStepIndex(0);
    }
    setIsPlaying(!isPlaying);
  };

  const handleStepForward = () => {
    setIsPlaying(false);
    if (currentStepIndex < steps.length - 1) {
      setCurrentStepIndex((prev) => prev + 1);
    }
  };

  const handleReset = () => {
    setIsPlaying(false);
    if (hasReducedMotion) {
      setCurrentStepIndex(steps.length - 1);
    } else {
      setCurrentStepIndex(0);
    }
  };

  if(request.loading) return <p role="status">Loading saved route legs...</p>;
  if(request.error) return <p role="alert">{request.error} <button onClick={request.reload}>Retry</button></p>;
  if (!currentStep) return <p role="status">No persisted travel legs are available to visualize.</p>;

  // Format final path display names
  const pathNames = currentStep.finalPath.map((id) => {
    const n = activeNodes.find((node) => node.id === id);
    return n ? n.shortName : id;
  });

  return (
    <div className="bg-white border-2 border-gold p-4 sm:p-5 space-y-4 shadow-sm relative font-mono text-xs">
      {/* Top Header & Framing Caption */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-stone/30 pb-3">
        <div>
          <div className="flex items-center gap-2 text-gold uppercase tracking-wider text-[11px] font-bold">
            <Cpu className="w-4 h-4 text-gold" />
            <span>Dijkstra Shortest-Path Algorithm Engine</span>
          </div>
          <h4 className="font-display text-lg text-ink font-bold">
            Live Graph Execution Matrix
          </h4>
        </div>

        {/* Start / Target Selector */}
        <div className="flex items-center gap-2 text-[11px]">
          <span className="text-stone font-bold uppercase">Route:</span>
          <select
            value={startId}
            onChange={(e) => setStartId(e.target.value)}
            aria-label="Select start node for route calculation"
            className="bg-salt border border-stone/40 text-charcoal font-mono px-2 py-1 text-[11px] outline-none"
          >
            {activeNodes.map((n) => (
              <option key={n.id} value={n.id}>
                Start: {n.shortName}
              </option>
            ))}
          </select>
          <span className="text-madder font-bold">→</span>
          <select
            value={targetId}
            onChange={(e) => setTargetId(e.target.value)}
            aria-label="Select target node for route calculation"
            className="bg-salt border border-stone/40 text-charcoal font-mono px-2 py-1 text-[11px] outline-none"
          >
            {activeNodes.map((n) => (
              <option key={n.id} value={n.id}>
                Target: {n.shortName}
              </option>
            ))}
          </select>
        </div>
      </div>

      <p className="text-[11px] font-body text-stone italic border-l-2 border-gold pl-2">
        "Dijkstra finds the shortest path between two attractions when they
        aren't directly connected -- most stops in your route are direct, this
        shows what happens when one isn't."
      </p>

      {/* Reduced Motion Warning Note */}
      {hasReducedMotion && (
        <div className="p-2.5 bg-ink text-salt border border-stone/40 text-[11px] flex items-center gap-2">
          <Info className="w-4 h-4 text-gold shrink-0" />
          <span>
            Animation reduced per your system settings. Displaying computed
            final shortest path directly.
          </span>
        </div>
      )}

      {/* SVG GRAPH CANVAS */}
      <div className="bg-salt/90 border-2 border-stone/30 relative h-[320px] sm:h-[350px] w-full overflow-auto p-2 shadow-inner">
        <div className="absolute inset-0 bg-stepwell-pattern opacity-10 pointer-events-none" />

        <svg
          className="w-full h-full"
          viewBox="0 0 500 360"
          preserveAspectRatio="xMidYMid meet"
          aria-label="Interactive Dijkstra Graph Visualization"
        >
          {/* 1. DRAW ALL GRAPH EDGES */}
          {activeEdges.map((edge) => {
            const fromNode = activeNodes.find((n) => n.id === edge.from);
            const toNode = activeNodes.find((n) => n.id === edge.to);
            if (!fromNode || !toNode) return null;

            // Check if this edge is part of the final shortest path
            const isInFinalPath =
              currentStep.isComplete &&
              currentStep.finalPath.some((id, idx) => {
                if (idx === currentStep.finalPath.length - 1) return false;
                const nextId = currentStep.finalPath[idx + 1];
                return (
                  (id === edge.from && nextId === edge.to) ||
                  (id === edge.to && nextId === edge.from)
                );
              });

            // Check if edge is currently active/relaxed
            const isActive =
              currentStep.activeEdge &&
              ((currentStep.activeEdge.from === edge.from &&
                currentStep.activeEdge.to === edge.to) ||
                (currentStep.activeEdge.from === edge.to &&
                  currentStep.activeEdge.to === edge.from));

            const isRelaxed =
              currentStep.relaxedEdge &&
              ((currentStep.relaxedEdge.from === edge.from &&
                currentStep.relaxedEdge.to === edge.to) ||
                (currentStep.relaxedEdge.from === edge.to &&
                  currentStep.relaxedEdge.to === edge.from));

            let strokeColor: string = SVG_COLORS.stone; // default neutral stone
            let strokeWidth = 1.5;
            let strokeDash = "4 3";

            if (isInFinalPath) {
              strokeColor = SVG_COLORS.madder; // Madder Red solid
              strokeWidth = 3.5;
              strokeDash = "none";
            } else if (isRelaxed || isActive) {
              strokeColor = SVG_COLORS.madder; // Highlight edge in Madder Red
              strokeWidth = 3;
              strokeDash = "none";
            }

            const midX = (fromNode.x + toNode.x) / 2;
            const midY = (fromNode.y + toNode.y) / 2;

            return (
              <g key={`${edge.from}-${edge.to}`}>
                <line
                  x1={fromNode.x}
                  y1={fromNode.y}
                  x2={toNode.x}
                  y2={toNode.y}
                  stroke={strokeColor}
                  strokeWidth={strokeWidth}
                  strokeDasharray={strokeDash}
                  className="transition-all duration-300"
                />

                {/* Distance Label Badge */}
                <rect
                  x={midX - 14}
                  y={midY - 8}
                  width="28"
                  height="14"
                  fill={SVG_COLORS.salt}
                  stroke={SVG_COLORS.stone}
                  rx="2"
                />
                <text
                  x={midX}
                  y={midY + 3}
                  textAnchor="middle"
                  fill={SVG_COLORS.charcoal}
                  fontSize="8"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="600"
                >
                  {edge.distanceKm}k
                </text>
              </g>
            );
          })}

          {/* 2. DRAW GRAPH NODES */}
          {activeNodes.map((node) => {
            const isStart = node.id === startId;

            const isCurrent = currentStep.currentNodeId === node.id;
            const isVisited = currentStep.visitedNodeIds.includes(node.id);
            const isFrontier = currentStep.frontierNodeIds.includes(node.id);
            const isInFinalPath =
              currentStep.isComplete && currentStep.finalPath.includes(node.id);

            let fillColor: string = SVG_COLORS.white; // default
            let strokeColor: string = SVG_COLORS.stone;
            let textColor: string = SVG_COLORS.charcoal;
            let isPulsing = false;

            if (isCurrent) {
              fillColor = SVG_COLORS.gold; // Stepwell Gold highlight for active node
              strokeColor = SVG_COLORS.ink;
              textColor = SVG_COLORS.ink;
            } else if (isInFinalPath) {
              fillColor = SVG_COLORS.madder; // Madder Red for path
              strokeColor = SVG_COLORS.gold;
              textColor = SVG_COLORS.white;
            } else if (isVisited) {
              fillColor = SVG_COLORS.ink; // Ink Indigo for visited
              strokeColor = SVG_COLORS.gold;
              textColor = SVG_COLORS.salt;
            } else if (isFrontier) {
              fillColor = SVG_COLORS.stone; // Stone Grey for frontier
              strokeColor = SVG_COLORS.gold;
              textColor = SVG_COLORS.charcoal;
              isPulsing = true;
            } else if (isStart) {
              fillColor = SVG_COLORS.gold;
              strokeColor = SVG_COLORS.ink;
            }

            const distVal = currentStep.distances[node.id];
            const distLabel = distVal === Infinity ? "∞" : `${distVal}k`;

            return (
              <g
                key={node.id}
                transform={`translate(${node.x}, ${node.y})`}
                className="transition-all duration-300 cursor-pointer"
              >
                {/* Outer Pulse Circle if Frontier */}
                {isPulsing && !hasReducedMotion && (
                  <circle
                    r="18"
                    fill="none"
                    stroke={SVG_COLORS.gold}
                    strokeWidth="1.5"
                    className="animate-ping opacity-60"
                  />
                )}

                {/* Node Circle */}
                <circle
                  r="14"
                  fill={fillColor}
                  stroke={strokeColor}
                  strokeWidth={isCurrent || isInFinalPath ? "3" : "2"}
                  className="transition-colors duration-300 shadow-md"
                />

                {/* Node Label Text */}
                <text
                  textAnchor="middle"
                  dy="4"
                  fill={textColor}
                  fontSize="9"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="bold"
                >
                  {node.shortName.substring(0, 3).toUpperCase()}
                </text>

                {/* Node Title & Distance Subtitle */}
                <text
                  textAnchor="middle"
                  y="26"
                  fill={SVG_COLORS.charcoal}
                  fontSize="9"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="bold"
                >
                  {node.shortName}
                </text>
                <text
                  textAnchor="middle"
                  y="36"
                  fill={SVG_COLORS.madder}
                  fontSize="8"
                  fontFamily="IBM Plex Mono, monospace"
                  fontWeight="600"
                >
                  [{distLabel}]
                </text>
              </g>
            );
          })}
        </svg>
      </div>

      {/* Step Description Line */}
      <div
        aria-live="polite"
        className="p-3 bg-ink text-salt border border-gold text-xs flex items-center justify-between gap-2"
      >
        <div className="flex items-center gap-2 truncate">
          <span className="bg-gold text-ink font-bold px-2 py-0.5 text-[10px] uppercase shrink-0">
            Step {currentStepIndex + 1}/{steps.length}
          </span>
          <span className="truncate text-stone text-[11px]">
            {currentStep.description}
          </span>
        </div>
        {currentStep.isComplete && (
          <span className="text-gold font-bold flex items-center gap-1 shrink-0 text-[11px]">
            <CheckCircle className="w-3.5 h-3.5 text-gold" />
            <span>Path Found</span>
          </span>
        )}
      </div>

      {/* Final Shortest Path Summary Line */}
      {currentStep.isComplete && currentStep.finalPath.length > 0 && (
        <div className="p-3 bg-madder/10 border border-madder text-ink font-mono text-xs font-bold flex flex-wrap items-center justify-between gap-2 animate-fadeIn">
          <div className="flex items-center gap-2">
            <span className="text-madder uppercase font-bold text-[10px] bg-madder text-salt px-2 py-0.5">
              Shortest Path
            </span>
            <span>{pathNames.join(" → ")}</span>
          </div>
          <div className="text-madder text-sm">
            · {currentStep.finalDistance} km
          </div>
        </div>
      )}

      {/* PLAYBACK CONTROLS: Play, Pause, Step Forward, Reset */}
      <div className="flex flex-wrap items-center justify-between gap-3 pt-2 border-t border-stone/30">
        <div className="flex items-center gap-2">
          {/* Play/Pause Button */}
          <button
            onClick={handlePlayPause}
            aria-label={
              isPlaying
                ? "Pause algorithm execution"
                : "Play algorithm execution"
            }
            className="bg-ink hover:bg-ink/90 text-salt border border-gold px-3 py-1.5 text-xs font-mono font-bold flex items-center gap-1.5 transition-colors cursor-pointer"
          >
            {isPlaying ? (
              <>
                <Pause className="w-3.5 h-3.5 text-gold" />
                <span>Pause</span>
              </>
            ) : (
              <>
                <Play className="w-3.5 h-3.5 text-gold" />
                <span>Play</span>
              </>
            )}
          </button>

          {/* Step Forward Button */}
          <button
            onClick={handleStepForward}
            disabled={currentStepIndex >= steps.length - 1}
            aria-label="Step forward to next step"
            className="bg-salt hover:bg-stone/20 text-charcoal border border-stone/40 px-3 py-1.5 text-xs font-mono font-bold flex items-center gap-1.5 transition-colors cursor-pointer disabled:opacity-40"
          >
            <SkipForward className="w-3.5 h-3.5 text-ink" />
            <span>Step forward</span>
          </button>

          {/* Reset Button */}
          <button
            onClick={handleReset}
            aria-label="Reset algorithm to step 1"
            className="bg-salt hover:bg-stone/20 text-charcoal border border-stone/40 px-3 py-1.5 text-xs font-mono font-bold flex items-center gap-1.5 transition-colors cursor-pointer"
          >
            <RotateCcw className="w-3.5 h-3.5 text-stone" />
            <span>Reset</span>
          </button>
        </div>

        {/* Color Legend */}
        <div className="flex flex-wrap items-center gap-3 text-[10px] text-stone">
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-gold inline-block border border-ink" />{" "}
            Start/Current
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-stone/50 inline-block border border-gold" />{" "}
            Frontier
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-ink inline-block border border-gold" />{" "}
            Visited
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2.5 h-2.5 rounded-full bg-madder inline-block border border-gold" />{" "}
            Path
          </span>
        </div>
      </div>
    </div>
  );
};
